CREATE OR REPLACE FUNCTION public.acces_reserve_raison_interne(p_nom text, p_batiment text, p_piece text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_loc text; v_n integer;
BEGIN
  IF NOT public.acces_piece_reservee_interne(p_batiment, p_piece) THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM public.acces_intrusions WHERE acteur = p_nom AND batiment = p_batiment) THEN RETURN NULL; END IF;
  IF p_batiment = 'pavillon-ambassadeurs-novomirsk' THEN
    RETURN CASE WHEN public.acces_dignitaire_interne(p_nom) THEN NULL ELSE 'acces_dignitaires' END;
  END IF;
  v_loc := public.residence_locataire_interne(p_piece);
  IF v_loc IS NULL THEN RETURN 'location_requise'; END IF;
  IF v_loc = p_nom THEN RETURN NULL; END IF;
  -- Une seule personne accompagne le locataire : membre de son groupe, groupe d'un seul membre.
  IF EXISTS (SELECT 1 FROM public.groupes_pj_adhesions WHERE membre = p_nom AND chef = v_loc) THEN
    SELECT count(*) INTO v_n FROM public.groupes_pj_adhesions WHERE chef = v_loc;
    RETURN CASE WHEN v_n <= 1 THEN NULL ELSE 'un_seul_invite' END;
  END IF;
  RETURN 'location_requise';
END $function$

CREATE OR REPLACE FUNCTION public.ambassade_acces_bureau_interne(p_empire text, p_nom text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_pays text; v_expire timestamptz;
BEGIN
  v_moi := p_nom;
  IF v_moi IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'acteur_non_authentifie');
  END IF;
  IF public.ambassade_identite(p_empire) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'ambassade_inconnue');
  END IF;
  SELECT country INTO v_pays FROM public.personnages_donnees WHERE name = v_moi;
  IF EXISTS (SELECT 1 FROM public.ambassades_ouvertes a
              WHERE a.pays_hote = v_pays AND a.empire = p_empire
                AND a.data ->> 'ambassadeur' = v_moi) THEN
    RETURN jsonb_build_object('ok', true, 'motif', 'ambassadeur');
  END IF;
  PERFORM public.ambassades_asiles_echoir(v_moi);
  IF public.ambassade_refuge_de(v_moi) = p_empire THEN
    RETURN jsonb_build_object('ok', true, 'motif', 'refugie');
  END IF;
  PERFORM public.ambassades_audiences_echoir(v_moi);
  SELECT expire_le INTO v_expire FROM public.ambassades_audiences
   WHERE demandeur = v_moi AND pays_hote = v_pays AND empire = p_empire AND statut = 'accordee' AND expire_le > now();
  IF v_expire IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'motif', 'audience', 'expire_le', v_expire);
  END IF;
  RETURN jsonb_build_object('ok', false, 'raison', 'sur_audience');
END; $function$

CREATE OR REPLACE FUNCTION public.cellule_alerter_ministre(p_cellule_id text, p_couverture text, p_sujet text, p_corps text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_min text; v_pays text; v_destinataire text;
BEGIN
  SELECT c.pays_proprietaire, coalesce(c.ministere, 'min_def') INTO v_pays, v_min
    FROM public.cellules_renseignement c WHERE c.id = p_cellule_id;
  IF v_pays IS NULL THEN RETURN; END IF;

  -- Titulaire reel du poste : un PJ s'il y en a un, sinon le PNJ du registre.
  SELECT d.name INTO v_destinataire FROM public.personnages_donnees d
   WHERE d.country = v_pays AND d.poste ->> 'id' = v_min LIMIT 1;
  IF v_destinataire IS NULL THEN
    SELECT t.nom_pnj INTO v_destinataire FROM public.titulaires_pnj t
     WHERE t.country = v_pays AND t.poste_id = v_min LIMIT 1;
  END IF;
  IF v_destinataire IS NULL THEN RETURN; END IF;

  PERFORM public.mail_systeme_poser_interne(
          'Service de renseignement', v_destinataire, p_sujet, p_corps,
          to_char(now() AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY HH24:MI'));
END;
$function$

CREATE OR REPLACE FUNCTION public.detention_clore_interne(p_nom text, p_mode text, p_jour integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_jour integer; v_peine jsonb; v_det record; v_qhs boolean; v_bat text; v_piece text; v_req jsonb; v_pays_inc text;
BEGIN
  IF coalesce(btrim(p_mode),'') = '' THEN
    RAISE EXCEPTION 'detention_clore_interne : le mode de fin est obligatoire';
  END IF;
  SELECT coalesce(day,1), est_emprisonne INTO v_jour, v_peine
    FROM public.personnages_donnees WHERE name = p_nom FOR UPDATE;
  SELECT * INTO v_det FROM public.detention_active(p_nom);
  -- Le caractere QHS se lit des DEUX cotes : la fiche peut le porter sans la ligne, et l'inverse.
  v_qhs := coalesce((v_peine->>'qhs')::boolean,false) OR coalesce(v_det.qhs,false);
  -- 1. La ligne. `AND mode_fin IS NULL` : une ligne deja close n'est pas reecrite.
  IF v_det.id IS NOT NULL THEN
    UPDATE public.detentions
       SET mode_fin = p_mode, jour_fin_effective = coalesce(p_jour, v_jour),
           date_fin_effective = now()
     WHERE id = v_det.id AND mode_fin IS NULL;
  END IF;
  -- 2. et 3. La fiche, et le drapeau en OBJET -- la forme que pa_repos_nocturne sait lire.
  UPDATE public.personnages_donnees
     SET est_emprisonne = NULL,
         detention_qhs = CASE WHEN v_qhs
           THEN jsonb_build_object('enQHS', false, 'paLimite1Jour', false) ELSE detention_qhs END
   WHERE name = p_nom;
  -- liberation_qhs_retour_serveur_v1 : arrivée identique à transport_effectuer.
  IF v_qhs AND p_mode = 'purgee' AND nullif(v_peine->>'retourVille','') IS NOT NULL THEN
    SELECT n.batiment, n.pieces->>0 INTO v_bat, v_piece FROM public.navigation_lieux_regles n
     JOIN public.personnages_donnees d ON d.name = p_nom AND n.pays = d.country
     WHERE n.ville = v_peine->>'retourVille' AND n.batiment LIKE 'centre-multinodal-%'
       AND NOT EXISTS(SELECT 1 FROM public.navigation_lieux_regles autre WHERE autre.pays = n.pays
           AND autre.ville <> n.ville AND autre.batiment = n.batiment)
     ORDER BY n.batiment LIMIT 1;
    IF v_bat IS NULL THEN RAISE EXCEPTION 'liberation_retour_non_reference: %', v_peine->>'retourVille'; END IF;
    UPDATE public.personnages_donnees SET current_city = v_peine->>'retourVille', current_building = v_bat,
           current_room = v_piece, current_street = NULL, updated_at = clock_timestamp() WHERE name = p_nom;
  END IF;
  -- incorporation_differee_v1 : un déserteur qui a accepté l'incorporation est conduit à la
  -- caserne à sa libération (pas à une évasion), si la mobilisation dure encore.
  IF p_mode NOT IN ('evasion', 'incorporation', 'poursuites_eteintes') THEN
    SELECT requisition, coalesce(country, 'republic') INTO v_req, v_pays_inc
      FROM public.personnages_donnees WHERE name = p_nom;
    IF coalesce((v_req->>'incorporationDifferee')::boolean, false) THEN
      UPDATE public.personnages_donnees SET requisition = v_req - 'incorporationDifferee' WHERE name = p_nom;
      IF coalesce((SELECT (b.data->>'mobilisationNationaleActive')::boolean FROM public.budgets_nationaux b
                    WHERE b.id = v_pays_inc), false)
         AND EXISTS (SELECT 1 FROM public.navigation_lieux_regles n WHERE n.pays = v_pays_inc
                      AND n.ville = public.caserne_ville(v_pays_inc) AND n.batiment = 'caserne-militaire' AND n.pieces ? 'corps_garde') THEN
        UPDATE public.personnages_donnees SET current_city = public.caserne_ville(v_pays_inc), current_building = 'caserne-militaire',
               current_room = 'corps_garde', current_street = public.caserne_noeud(v_pays_inc), updated_at = clock_timestamp()
         WHERE name = p_nom;
        PERFORM public.mail_systeme_poser_interne('Caserne', p_nom, 'Incorporation',
          'Votre peine est terminée : comme vous l''aviez accepté, vous êtes conduit(e) à la caserne et incorporé(e).');
      END IF;
    END IF;
  END IF;
  -- 4. Le registre du QHS, sans quoi le Ministere voit un detenu libre.
  IF v_qhs THEN
    UPDATE public.prisonniers_qhs SET statut='libere'
     WHERE data ->> 'nom' = p_nom AND coalesce(statut,'') = 'detenu';
  END IF;
  RETURN jsonb_build_object('detention_id', v_det.id, 'sortait_du_qhs', v_qhs,
                            'jour', coalesce(p_jour, v_jour),
                            'retour_ville', v_peine ->> 'retourVille');
END; $function$

CREATE OR REPLACE FUNCTION public.detention_ouvrir_interne(p_nom text, p_raison text, p_jours integer, p_city text, p_country text, p_motifs jsonb, p_autorite text, p_issue text, p_extras jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id text := 'det-' || (extract(epoch from clock_timestamp())*1000)::bigint || '-' || substr(md5(random()::text),1,6);
  v_jour_cible integer; v_deja jsonb; v_pnj record; v_cellule text;
  v_x jsonb := CASE WHEN jsonb_typeof(p_extras)='object' THEN p_extras ELSE '{}'::jsonb END;
  v_ville_cond text; v_jour_aff integer; v_prec text; v_reliquat integer; v_retour text;
BEGIN
 -- ecrou_verrou_graphe_v1
 PERFORM pg_advisory_xact_lock(hashtextextended('groupe_pj:graphe',0));
  -- Chacune de ces cinq valeurs vaut NULL quand p_extras l'ignore : un appel a huit arguments
  -- produit donc exactement la ligne qu'il produisait avant ce lot.
  v_ville_cond := coalesce(nullif(v_x->>'ville_condamnation',''), p_city);
  v_jour_aff   := nullif(v_x->>'jour_affaire','')::integer;
  v_prec       := nullif(v_x->>'detention_precedente_id','');
  v_reliquat   := nullif(v_x->>'reliquat_jours','')::integer;
  v_retour     := nullif(v_x->>'retour_ville','');
  SELECT coalesce(d.day,1), d.est_emprisonne INTO v_jour_cible, v_deja
    FROM public.personnages_donnees d WHERE d.name = p_nom FOR UPDATE;
  -- Asile politique (25/10/2026) : un refugie au Quartier des Ambassades n'est pas arretable.
  IF FOUND AND public.ambassade_refugie_protege(p_nom) THEN
    RETURN jsonb_build_object('ok',false,'raison','refugie_protege');
  END IF;
  IF NOT FOUND THEN
    SELECT * INTO v_pnj FROM public.detention_cible_pnj(p_nom, p_country);
    IF v_pnj.systeme IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','cible_introuvable'); END IF;
    IF v_pnj.statut = 'detenu' THEN RETURN jsonb_build_object('ok',false,'raison','cible_deja_detenue'); END IF;
    IF NOT v_pnj.arretable THEN
      RETURN jsonb_build_object('ok',false,'raison','cible_non_arretable','niveau_connu',v_pnj.niveau_connu,'niveau_requis',2);
    END IF;
    v_jour_cible := public.jour_de_jeu_pays(p_country);
    INSERT INTO public.detentions (id,country,city,nom,raison,jour_debut,jour_fin,qhs,motifs,
             autorite,issue_judiciaire,ville_condamnation,provenance,jour_affaire,detention_precedente_id,reliquat_jours)
    VALUES (v_id,p_country,p_city,p_nom,p_raison,v_jour_cible,v_jour_cible+p_jours,false,p_motifs,
             p_autorite,p_issue,v_ville_cond,v_pnj.systeme,v_jour_aff,v_prec,v_reliquat);
    UPDATE public.agents_renseignement
       SET statut='detenu', detention_id=v_id, detenu_depuis=now(), leader_courant=NULL, maj_le=now()
     WHERE id = v_pnj.agent_id RETURNING cellule_id INTO v_cellule;
    PERFORM public.cellule_alerter_ministre(v_cellule, p_nom, 'Agent arrete — ' || p_nom,
      'Votre agent operant sous l''identite de couverture « ' || p_nom ||
      ' » a ete arrete par les autorites de ' || p_country || ' a ' || p_city ||
      '. Il ne peut plus collecter ni etre deplace.');
    RETURN jsonb_build_object('ok',true,'detention_id',v_id,'jour_debut',v_jour_cible,
                              'jour_fin',v_jour_cible+p_jours,'provenance',v_pnj.systeme);
  END IF;
  -- LA GARDE DE REJEU : une peine en cours interdit d'en ouvrir une seconde. C'est elle qui rend
  -- un double appel inoffensif, et elle existait avant ce lot.
  IF v_deja IS NOT NULL AND jsonb_typeof(v_deja)='object' THEN
    RETURN jsonb_build_object('ok',false,'raison','cible_deja_detenue');
  END IF;
  INSERT INTO public.detentions (id,country,city,nom,raison,jour_debut,jour_fin,qhs,motifs,
           autorite,issue_judiciaire,ville_condamnation,jour_affaire,detention_precedente_id,reliquat_jours)
  VALUES (v_id,p_country,p_city,p_nom,p_raison,v_jour_cible,v_jour_cible+p_jours,false,p_motifs,
           p_autorite,p_issue,v_ville_cond,v_jour_aff,v_prec,v_reliquat);
  UPDATE public.personnages_donnees
     SET est_emprisonne = jsonb_build_object('jours',p_jours,'jourFin',v_jour_cible+p_jours,
           'raison',p_raison,'detentionId',v_id,'qhs',false,'city',p_city,'country',p_country,
           'debutTs',(extract(epoch from clock_timestamp())*1000)::bigint)
         || CASE WHEN v_retour IS NOT NULL THEN jsonb_build_object('retourVille',v_retour) ELSE '{}'::jsonb END
   WHERE name = p_nom;
  -- ecrou_separation_groupe_v1
  PERFORM public.groupe_ecrou_separer_interne(p_nom);
  -- detention_cellule_serveur_v1
  IF NOT EXISTS(SELECT 1 FROM public.navigation_lieux_regles WHERE pays=p_country AND ville=p_city AND batiment=CASE WHEN p_city='qhs' THEN 'qhs-prison' WHEN p_city='capitale' THEN 'commissariat' ELSE 'commissariat-local' END AND pieces ? CASE WHEN p_city='qhs' THEN 'cellules_qhs' WHEN p_city='capitale' THEN 'prison' ELSE 'geoles' END) THEN RAISE EXCEPTION 'cellule_non_referencee';END IF;
  UPDATE public.personnages_donnees SET country=p_country,current_city=p_city,current_building=CASE WHEN p_city='qhs' THEN 'qhs-prison' WHEN p_city='capitale' THEN 'commissariat' ELSE 'commissariat-local' END,current_room=CASE WHEN p_city='qhs' THEN 'cellules_qhs' WHEN p_city='capitale' THEN 'prison' ELSE 'geoles' END,current_street=NULL,updated_at=clock_timestamp() WHERE name=p_nom;
  RETURN jsonb_build_object('ok',true,'detention_id',v_id,'jour_debut',v_jour_cible,'jour_fin',v_jour_cible+p_jours);
END; $function$

CREATE OR REPLACE FUNCTION public.dossier_acte_consigner(p_affaire text, p_pays text, p_ville text, p_type text, p_acteur text DEFAULT NULL::text, p_acteur_poste text DEFAULT NULL::text, p_qualif_avant text DEFAULT NULL::text, p_qualif_apres text DEFAULT NULL::text, p_donnees jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_rang integer; v_id text;
BEGIN
  -- ELLE LEVE, ELLE NE REFUSE PAS. Tous ses appelants sont internes et l'invoquent par PERFORM,
  -- qui jette la valeur rendue : un refus propre serait un trou silencieux dans la chronologie.
  -- En levant, elle annule la transaction entiere -- l'acte judiciaire ET sa trace, ou ni l'un ni
  -- l'autre.
  IF NOT EXISTS (SELECT 1 FROM public.dossiers_judiciaires_actes_types t WHERE t.type = p_type) THEN
    RAISE EXCEPTION 'chronologie judiciaire : type d''acte inconnu (%)', p_type;
  END IF;
  IF coalesce(btrim(coalesce(p_affaire, '')), '') = '' THEN
    RAISE EXCEPTION 'chronologie judiciaire : acte sans affaire';
  END IF;
  IF coalesce(btrim(coalesce(p_pays, '')), '') = '' THEN
    RAISE EXCEPTION 'chronologie judiciaire : acte sans pays (affaire %)', p_affaire;
  END IF;

  -- LE RANG EST CALCULE PAR LE SERVEUR. La contrainte UNIQUE (affaire, rang) fait le reste :
  -- deux actes simultanes sur la meme affaire ne peuvent pas partager un rang.
  SELECT coalesce(max(a.rang), 0) + 1 INTO v_rang
    FROM public.dossiers_judiciaires_actes a WHERE a.affaire = p_affaire;
  v_id := 'acte-' || p_affaire || '-' || v_rang;
  INSERT INTO public.dossiers_judiciaires_actes
    (id, affaire, pays, ville, rang, type, acteur, acteur_poste,
     qualif_avant, qualif_apres, donnees)
  VALUES (v_id, p_affaire, p_pays, p_ville, v_rang, p_type, p_acteur, p_acteur_poste,
          p_qualif_avant, p_qualif_apres, p_donnees);
  RETURN jsonb_build_object('ok', true, 'acte', v_id, 'rang', v_rang);
END;
$function$

CREATE OR REPLACE FUNCTION public.escort_lieu_locataire_interne(p_nom text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d record; j date := (now() AT TIME ZONE 'Europe/Paris')::date;
BEGIN
  SELECT country, current_city, current_building, current_room INTO d FROM public.personnages_donnees WHERE name = p_nom;
  IF NOT FOUND OR d.country IS DISTINCT FROM 'soviet' OR d.current_city IS DISTINCT FROM 'capitale' THEN RETURN NULL; END IF;
  IF d.current_building = 'pavillon-ambassadeurs-novomirsk'
     AND d.current_room IN ('suite_privee', 'suite_presidentielle', 'suite_parti')
     AND EXISTS (SELECT 1 FROM public.pavillon_baux pb WHERE pb.piece = d.current_room AND pb.locataire = p_nom
                   AND pb.statut = 'actif' AND pb.debut <= j AND pb.fin_excl > j) THEN
    RETURN jsonb_build_object('batiment', d.current_building, 'piece', d.current_room, 'lieu', 'pavillon');
  END IF;
  IF d.current_building = 'residence-imperiale-novomirsk'
     AND EXISTS (SELECT 1 FROM public.residence_locations l WHERE l.locataire = p_nom AND l.piece = d.current_room AND l.fin > now()) THEN
    RETURN jsonb_build_object('batiment', d.current_building, 'piece', d.current_room, 'lieu', 'residence');
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.escort_piratage_nuit_interne(p_nom text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_lieu jsonb; v_escort text; v_n integer; d public.dossiers_informatiques; v_objets text[];
  v_jour date := (now() AT TIME ZONE 'Europe/Paris')::date; p record;
BEGIN
  v_lieu := public.escort_lieu_locataire_interne(p_nom);
  IF v_lieu IS NULL THEN RETURN; END IF;
  SELECT m.nom INTO v_escort FROM public.pnj_membres m JOIN public.pnj_employes_metier em ON em.pnj_id = m.id
   WHERE m.famille = 'employe' AND m.proprietaire_pj = p_nom AND m.statut = 'actif' AND em.job = 'escort'
   ORDER BY random() LIMIT 1;
  IF v_escort IS NULL THEN RETURN; END IF;
  INSERT INTO public.escort_piratages_nuits (nom, jour) VALUES (p_nom, v_jour) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN; END IF;
  SELECT * INTO p FROM public.personnages_donnees WHERE name = p_nom;
  -- Ordinateurs « venus avec lui » : dans l'inventaire, ou installés dans la pièce louée.
  SELECT array_agg(x) INTO v_objets FROM (
    SELECT o->>'id' x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p.inventory) = 'array' THEN p.inventory ELSE '[]'::jsonb END) o
     WHERE coalesce(o->>'generique_id', o->>'type') = 'ordinateur-complet' AND coalesce(o->>'id', '') <> ''
    UNION SELECT e.objet->>'id' FROM public.equipements_installes e
     WHERE e.proprietaire = p_nom AND e.generique_id = 'ordinateur-complet' AND e.pays = p.country AND e.ville = p.current_city
       AND e.batiment = p.current_building AND e.piece = p.current_room) q;
  IF v_objets IS NULL OR random() >= 0.25 THEN RETURN; END IF;
  SELECT * INTO d FROM public.dossiers_informatiques WHERE objet_id = ANY (v_objets) ORDER BY random() LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  PERFORM public.interieur_dossier_deposer_interne('soviet', 'dossier_pirate', p_nom,
    'Dossier copié chez ' || p_nom || ' : ' || coalesce(d.titre, 'sans titre'), coalesce(d.contenu, ''),
    jsonb_build_object('escort', v_escort, 'type', d.type, 'donnees', d.donnees),
    'Ministère de la Sécurité du Peuple', 'Dossier informatique copié — ' || p_nom,
    'Pendant la nuit, ' || v_escort || ' a copié un dossier de l''ordinateur de ' || p_nom || ' : « ' || coalesce(d.titre, 'sans titre')
    || E' ».\n\nLa copie est conservée dans votre bureau (« Dossiers confidentiels »).');
  -- La trace d'un acte illégal ordinaire, au nom de l'escort ; la victime n'est pas prévenue.
  INSERT INTO public.actions_tracables (id, auteur, cible, type_action, country, city, jour, jour_expiration)
  VALUES ('action-' || replace(gen_random_uuid()::text, '-', ''), v_escort, p_nom, 'pirater', p.country, p.current_city,
          coalesce(p.day, 1), coalesce(p.day, 1) + 7);
END $function$

CREATE OR REPLACE FUNCTION public.groupe_ecrou_separer_interne(p_nom text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE ids text[];pj_ids text[];positions jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('groupe_pj:graphe',0));
 SELECT array_agg(g.identifiant ORDER BY g.identifiant) FILTER(WHERE g.est_pj)
 INTO pj_ids FROM public.groupe_participants_interne(p_nom) g;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::text[]) INTO ids
 FROM public.pnj_membres WHERE leader_pj=p_nom;
 PERFORM public.pnj_groupes_verrouiller_projections_interne(ids);
 PERFORM name FROM public.personnages_donnees WHERE name=ANY(pj_ids) ORDER BY name FOR UPDATE;
 PERFORM id FROM public.pnj_membres WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_object_agg(m.id,to_jsonb(pe)),'{}'::jsonb) INTO positions
 FROM public.pnj_membres m CROSS JOIN LATERAL public.pnj_position_effective(m.id) pe
 WHERE m.id=ANY(ids);
 PERFORM public.pnj_positions_separer_interne(positions);
 -- Si le chef est écroué, chaque PJ reste à sa position ; aucun nouveau chef
 -- ou ordre de déplacement n'est choisi arbitrairement. Un membre écroué
 -- quitte uniquement son adhésion. Identités/emplois/propriétés conservés.
 DELETE FROM public.groupes_pj_adhesions WHERE membre=p_nom OR chef=p_nom;
 PERFORM public.pnj_groupes_projeter_interne(ids);
END $function$

CREATE OR REPLACE FUNCTION public.infraction_canonique(p_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id text; v_canon text;
BEGIN
  v_id := nullif(btrim(coalesce(p_id, '')), '');
  IF v_id IS NULL THEN RETURN NULL; END IF;
  SELECT a.canonique INTO v_canon FROM public.infractions_alias a WHERE a.alias = v_id;
  IF v_canon IS NOT NULL THEN v_id := v_canon; END IF;
  IF EXISTS (SELECT 1 FROM public.infractions i WHERE i.id = v_id) THEN RETURN v_id; END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.infraction_peine_bornes(p_infraction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id text; v_i record; v_jmin integer; v_jmax integer; v_amin integer; v_amax integer;
BEGIN
  v_id := public.infraction_canonique(p_infraction);
  IF v_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'infraction_inconnue',
                              'demande', p_infraction);
  END IF;
  SELECT * INTO v_i FROM public.infractions WHERE id = v_id;

  -- round() de PostgreSQL arrondit au plus proche, les demis vers le haut : round(0.5) = 1 et
  -- round(1.5) = 2. C'est la meme convention que Math.round cote navigateur.
  v_jmin := greatest(1, round(v_i.jours_reference * 0.5)::integer);
  v_jmax := round(v_i.jours_reference * 1.5)::integer;
  v_amin := greatest(0, round(v_i.amende_reference * 0.5)::integer);
  v_amax := round(v_i.amende_reference * 1.5)::integer;

  RETURN jsonb_build_object('ok', true,
    'infraction', v_i.id, 'libelle', v_i.libelle, 'categorie', v_i.categorie,
    'bareme_propre', v_i.bareme_propre, 'detectable', v_i.detectable,
    'jours_reference', v_i.jours_reference, 'jours_min', v_jmin, 'jours_max', v_jmax,
    'amende_reference', v_i.amende_reference, 'amende_min', v_amin, 'amende_max', v_amax,
    -- VRAI quand la borne basse EGALE la reference : l'attenuation est alors inexprimable, le
    -- juge ne peut qu'aggraver. Les huit infractions a 1 jour sont dans ce cas.
    'plancher_technique', (v_jmin >= v_i.jours_reference));
END;
$function$

CREATE OR REPLACE FUNCTION public.interieur_dossier_deposer_interne(p_pays text, p_type text, p_cible text, p_titre text, p_contenu text, p_donnees jsonb, p_expediteur text, p_sujet text, p_corps text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint; v_ministre text := public.interieur_ministre_pj_interne(p_pays);
BEGIN
  INSERT INTO public.interieur_dossiers (pays, type, cible, titre, contenu, donnees)
  VALUES (p_pays, p_type, p_cible, left(p_titre, 200), p_contenu, coalesce(p_donnees, '{}'::jsonb)) RETURNING id INTO v_id;
  IF v_ministre IS NOT NULL THEN
    PERFORM public.mail_systeme_poser_interne(p_expediteur, v_ministre, p_sujet, p_corps, NULL);
  ELSIF p_type = 'projet_article' THEN
    -- Ministre PNJ : publication une fois sur deux (Fred, 12/11/2026), sinon le projet attend dans le bureau.
    IF random() < 0.5 THEN PERFORM public.interieur_publier_interne(v_id, 'PNJ');
    ELSE UPDATE public.interieur_dossiers SET statut = 'en_attente', decide_par = 'PNJ', decide_le = now() WHERE id = v_id;
    END IF;
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.interieur_publier_interne(p_id bigint, p_par text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d public.interieur_dossiers;
BEGIN
  SELECT * INTO d FROM public.interieur_dossiers WHERE id = p_id AND type = 'projet_article' FOR UPDATE;
  IF NOT FOUND OR d.statut = 'publie' THEN RETURN; END IF;
  INSERT INTO public.journal_articles_en_attente (id, country, rubrique, titre, texte, statut, origine, priorite, dedup_key, created_at)
  VALUES ('scandale-escort-' || p_id, d.pays, 'politique', d.titre, d.contenu, 'attente', 'scandale_escort', 'importante',
          'scandale-escort-' || p_id, now())
  ON CONFLICT (id) DO NOTHING;
  UPDATE public.interieur_dossiers SET statut = 'publie', decide_par = p_par, decide_le = now() WHERE id = p_id;
END $function$

CREATE OR REPLACE FUNCTION public.inventaire_deposer_interne(p_nom text, p_objet jsonb, p_automatique boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_inv jsonb; v_place integer; v_q integer; v_cle text; v_obj jsonb := p_objet; v_pile bigint;
BEGIN
  IF p_objet IS NULL OR jsonb_typeof(p_objet) <> 'object' THEN RETURN jsonb_build_object('ok', false, 'raison', 'objet_invalide'); END IF;
  SELECT coalesce(inventory,'[]'::jsonb) INTO v_inv
    FROM public.personnages_donnees WHERE name = p_nom FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable'); END IF;
  IF jsonb_typeof(v_inv) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('ok',false,'raison','inventaire_format_a_examiner'); END IF;
  v_place := CASE WHEN p_automatique THEN 1000000 ELSE public.inventaire_place_restante(v_inv) END;
  v_cle := nullif(p_objet ->> 'stackKey', '');
  IF coalesce((p_objet ->> 'stackable')::boolean, false) AND v_cle IS NOT NULL THEN
    IF coalesce((p_objet->>'qty')::numeric,1)<=0 OR coalesce((p_objet->>'qty')::numeric,1)<>trunc(coalesce((p_objet->>'qty')::numeric,1)) THEN
      RETURN jsonb_build_object('ok',false,'raison','quantite_invalide'); END IF;
    v_q := least(coalesce((p_objet->>'qty')::numeric,1),v_place)::integer;
    IF v_q <= 0 THEN RETURN jsonb_build_object('ok', false, 'raison', 'inventaire_plein'); END IF;
    SELECT o INTO v_pile FROM jsonb_array_elements(v_inv) WITH ORDINALITY x(e,o) WHERE coalesce((e->>'stackable')::boolean,false) AND e->>'stackKey'=v_cle ORDER BY o LIMIT 1;
    IF v_pile IS NOT NULL THEN
      SELECT jsonb_agg(CASE WHEN o=v_pile
                       THEN jsonb_set(e, '{qty}', to_jsonb(coalesce((e ->> 'qty')::numeric, 1) + v_q)) ELSE e END ORDER BY o)
        INTO v_inv FROM jsonb_array_elements(v_inv) WITH ORDINALITY x(e, o);
    ELSE
      v_inv := v_inv || jsonb_build_array(p_objet || jsonb_build_object('qty', v_q));
    END IF;
  ELSE
    v_q := greatest(1, coalesce((p_objet ->> 'encombrement')::numeric, 1)::integer);
    IF v_place < v_q THEN RETURN jsonb_build_object('ok', false, 'raison', 'inventaire_plein'); END IF;
    IF coalesce(p_objet ->> 'id', '') = '' THEN
      v_obj := p_objet || jsonb_build_object('id', 'obj-' || replace(gen_random_uuid()::text, '-', ''));
    END IF;
    v_inv := v_inv || jsonb_build_array(v_obj);
    v_q := 1;
  END IF;
  UPDATE public.personnages_donnees SET inventory = v_inv WHERE name = p_nom;
  RETURN jsonb_build_object('ok', true, 'qte', v_q)
    || (SELECT jsonb_build_object('inventory', inventory, 'revision', inventory_revision) FROM public.personnages_donnees WHERE name = p_nom);
END; $function$

CREATE OR REPLACE FUNCTION public.inventaire_revision_garder()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF coalesce(nullif(current_setting('role',true),'none'),session_user) IN ('anon','authenticated')
     AND coalesce(current_setting('request.path',true),'') NOT LIKE '/rpc/%' THEN
    NEW.inventory := OLD.inventory;
  END IF;
  NEW.inventory_revision := OLD.inventory_revision
    + CASE WHEN NEW.inventory IS DISTINCT FROM OLD.inventory THEN 1 ELSE 0 END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.jauges_effet_appliquer_interne(p_nom text, p_pop integer, p_inf integer, p_moral integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.personnages_donnees; res jsonb;
BEGIN
 SELECT * INTO r FROM public.personnages_donnees WHERE name=p_nom FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('jauges',NULL); END IF;
 res:=coalesce(r.resources,'{}'::jsonb)-'popBase'-'infBase';
 IF coalesce(p_pop,0)<>0 THEN res:=jsonb_set(res,'{pop}',to_jsonb(least(100,greatest(0,coalesce((res->>'pop')::numeric,0)+p_pop))));END IF;
 IF coalesce(p_inf,0)<>0 THEN res:=jsonb_set(res,'{inf}',to_jsonb(least(100,greatest(0,coalesce((res->>'inf')::numeric,0)+p_inf))));END IF;
 UPDATE public.personnages_donnees SET resources=res,
   moral=CASE WHEN coalesce(p_moral,0)<>0 THEN least(100,greatest(0,coalesce(moral,50)+p_moral)) ELSE moral END
  WHERE name=p_nom RETURNING * INTO r;
 RETURN jsonb_build_object('jauges',jsonb_build_object('pop',r.resources->'pop','inf',r.resources->'inf','moral',r.moral,
   'gain_pop',coalesce(p_pop,0),'gain_inf',coalesce(p_inf,0),'gain_moral',coalesce(p_moral,0)));
END;$function$

CREATE OR REPLACE FUNCTION public.juge_moi()
 RETURNS TABLE(nom text, pays text, ville text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_inc text; v_pays text; v_ville text; v_pnj text;
BEGIN
  RETURN QUERY
    SELECT d.name, d.country, coalesce(d.poste ->> 'city', 'capitale')
      FROM public.personnages_donnees d
     WHERE d.user_id = auth.uid() AND (d.poste ->> 'id') = 'juge'
     LIMIT 1;
  IF FOUND THEN RETURN; END IF;

  v_inc := public.incarnation_courante();
  IF v_inc IS NULL THEN RETURN; END IF;
  v_pays  := public.incarnation_pays();
  v_ville := public.incarnation_siege();
  IF v_pays IS NULL OR v_ville IS NULL THEN RETURN; END IF;
  v_pnj := public.admin_pnj_titulaire(v_pays, 'juge', v_ville);
  IF v_pnj IS NULL OR v_pnj IS DISTINCT FROM v_inc THEN RETURN; END IF;
  RETURN QUERY SELECT v_pnj, v_pays, v_ville;
END $function$

CREATE OR REPLACE FUNCTION public.justice_recherches(p_nom text)
 RETURNS TABLE(id text, country text, ville_condamnation text, motif text, jours integer, data jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_autorise boolean := false;
BEGIN
  IF public.est_appel_serveur() THEN
    v_autorise := true;
  ELSE
    v_moi := public.mon_personnage();
    IF v_moi IS NOT NULL THEN
      -- Soi-meme : un joueur peut savoir qu'il est recherche.
      IF v_moi = p_nom THEN
        v_autorise := true;
      ELSE
        -- Autorite judiciaire, dans son propre pays.
        SELECT true INTO v_autorise
          FROM public.acteur_poste_courant() a
          JOIN public.personnages_donnees c ON c.name = p_nom
         WHERE a.poste_id IN ('commissaire','juge','min_just','min_int','president')
           AND a.pays = c.country
         LIMIT 1;
      END IF;
    END IF;
  END IF;

  IF NOT coalesce(v_autorise, false) THEN RETURN; END IF;

  -- `motif_allegue` EST RETIRE DE CE QUI SORT (13 octobre 2026). C'est le texte libre du
  -- plaignant, recopie sur la condamnation depuis le dossier : il n'a rien a faire sur un avis de
  -- recherche, que l'autorite lit pour savoir QUI chercher, pour QUELLE qualification, OU et
  -- pour COMBIEN de jours. Le retrait est inconditionnel -- meme pour la personne recherchee
  -- elle-meme, qui lit le texte du plaignant sur SON dossier par sa propre porte, pas ici.
  RETURN QUERY SELECT * FROM public.douane_recherches_interne(p_nom);
END;
$function$

CREATE OR REPLACE FUNCTION public.justice_rendre_sentence(p_affaire_id text, p_infraction text, p_genre text, p_jours integer DEFAULT 0, p_amende integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_j record; v_brut text; v_a jsonb; v_ville text; v_pays text; v_jour integer;
  v_calc jsonb; v_jours integer; v_amende integer; v_libelle text; v_peine text;
  v_jug text; v_n integer; v_motifs jsonb; v_parquet text;
  v_det record; v_exec jsonb; v_executee boolean := false; v_jour_pays integer;
BEGIN
  IF coalesce(btrim(coalesce(p_affaire_id, '')), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'affaire_invalide'); END IF;

  SELECT p.data, p.city, p.country INTO v_brut, v_ville, v_pays
    FROM public.plaintes_en_cours p WHERE p.id = p_affaire_id FOR UPDATE;
  IF NOT FOUND OR v_brut IS NULL OR left(btrim(v_brut), 1) <> '{' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'affaire_absente'); END IF;
  v_a := v_brut::jsonb;

  SELECT * INTO v_j FROM public.juge_de_la_ville(v_ville);
  IF v_j.nom IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'pas_juge_de_cette_ville', 'ville', v_ville); END IF;

  IF coalesce(v_a ->> 'status', '') <> 'saisie' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'affaire_non_saisie',
                              'statut', v_a ->> 'status'); END IF;

  IF public.affaire_delai_expire(v_a, v_pays) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'delai_de_jugement_expire',
                              'echeance', (v_a ->> 'delai_jugement_jour')::integer); END IF;

  -- L'AUDIENCE OBLIGATOIRE (13 octobre 2026). Une affaire qui releve de la procedure complete ne
  -- se juge pas sans proces : l'audience doit avoir ete fixee ET OUVERTE. Le refus est place
  -- APRES le delai pour ne rien changer a l'ordre des refus existants -- une affaire dont le
  -- delai a expire est morte, audience ou pas.
  IF NOT public.affaire_audience_ouverte(v_a) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'audience_non_ouverte',
                              'audience_jour', (v_a ->> 'audience_jour')::integer); END IF;

  v_calc := public.justice_peine_calcul(p_infraction, p_genre, v_a ->> 'cible', v_pays);
  IF coalesce((v_calc ->> 'ok')::boolean, false) IS NOT TRUE THEN RETURN v_calc; END IF;

  v_jours  := coalesce(p_jours, 0);
  v_amende := coalesce(p_amende, 0);

  IF v_jours < (v_calc ->> 'jours_min')::integer
     OR v_jours > (v_calc ->> 'jours_max')::integer THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'peine_hors_bornes',
      'demande_jours', v_jours,
      'jours_min', (v_calc ->> 'jours_min')::integer,
      'jours_max', (v_calc ->> 'jours_max')::integer,
      'jours_reference', (v_calc ->> 'jours_reference')::integer);
  END IF;
  IF v_amende < (v_calc ->> 'amende_min')::integer
     OR v_amende > (v_calc ->> 'amende_max')::integer THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'amende_hors_bornes',
      'demande_amende', v_amende,
      'amende_min', (v_calc ->> 'amende_min')::integer,
      'amende_max', (v_calc ->> 'amende_max')::integer,
      'amende_reference', (v_calc ->> 'amende_reference')::integer);
  END IF;

  -- DEUX HORLOGES, ET CHACUNE A SA PLACE. `v_jour` est le compteur personnel du juge : il datait
  -- deja `jugements.jour` avant cette tranche, et le changer reecrirait l'histoire. `v_jour_pays`
  -- est l'horloge PARTAGEE, et c'est la seule sur laquelle une echeance OPPOSABLE puisse vivre --
  -- celui qui interjette appel n'est pas le juge.
  SELECT coalesce(d.day, 1) INTO v_jour FROM public.personnages_donnees d WHERE d.name = v_j.nom;
  v_jour := coalesce(v_jour, 1);
  v_jour_pays := coalesce(public.jour_de_jeu_pays(v_pays), 1);
  v_libelle := v_calc ->> 'libelle';
  v_parquet := v_a ->> 'qualification_parquet';

  v_peine := CASE p_genre
    WHEN 'prison'      THEN 'Prison ' || v_jours || ' jour' || CASE WHEN v_jours > 1 THEN 's' ELSE '' END
    WHEN 'amende'      THEN 'Amende de ' || v_amende || ' FR'
    WHEN 'amenagement' THEN 'Amenagement : pointage quotidien au commissariat'
    WHEN 'qhs'         THEN 'Envoi au QHS (' || v_jours || ' jours)'
    ELSE                    'Prison ' || v_jours || ' jours + popularite a zero'
  END;

  v_motifs := CASE WHEN v_jours > 0 THEN jsonb_build_array(jsonb_build_object(
      'type', v_libelle, 'infraction', v_calc ->> 'infraction', 'jours', v_jours,
      'city', v_ville, 'source', 'jugement',
      'date_evenement', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')))
    ELSE '[]'::jsonb END;

  v_jug := 'jug-' || p_affaire_id;
  INSERT INTO public.jugements (id, country, city, accuse, motif, peine, juge, jour, executee, data)
  VALUES (v_jug, v_pays, coalesce(v_ville, 'capitale'), v_a ->> 'cible',
          v_libelle, v_peine, v_j.nom, v_jour, false,
          jsonb_build_object(
            'verdict', 'condamnation', 'instance', 'premiere',
            'infraction', v_calc ->> 'infraction',
            'infraction_libelle', v_libelle,
            'genre', p_genre,
            'jours', v_jours, 'amende', v_amende,
            'jours_reference', (v_calc ->> 'jours_reference')::integer,
            'jours_min', (v_calc ->> 'jours_min')::integer,
            'jours_max', (v_calc ->> 'jours_max')::integer,
            'amende_reference', (v_calc ->> 'amende_reference')::integer,
            'jour_pays', v_jour_pays,
            'appel_jusqu_au_jour_pays', v_jour_pays + public.justice_fenetre_appel_jours(),
            'categorie_alleguee', v_a ->> 'categorie_alleguee',
            'motif_allegue', v_a ->> 'motif',
            'qualification_parquet', v_parquet,
            'motifs', v_motifs,
            'issue_judiciaire', v_peine))
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'jugement_deja_rendu');
  END IF;

  IF v_parquet IS NOT NULL AND (v_calc ->> 'infraction') IS DISTINCT FROM v_parquet THEN
    PERFORM public.dossier_acte_consigner(p_affaire_id, v_pays, v_ville,
      'requalification', v_j.nom, 'juge', v_parquet, v_calc ->> 'infraction');
  END IF;

  IF v_jours > 0 THEN
    SELECT * INTO v_det FROM public.detention_active(v_a ->> 'cible');
    IF v_det.id IS NULL THEN
      v_exec := public.detention_ouvrir_interne(
                  v_a ->> 'cible', v_libelle, v_jours, coalesce(v_ville, 'capitale'), v_pays,
                  v_motifs, v_j.nom, coalesce(v_peine, 'condamnation_executee'));
      IF coalesce((v_exec ->> 'ok')::boolean, false) THEN
        UPDATE public.jugements SET executee = true WHERE id = v_jug;
        v_executee := true;
      END IF;
    END IF;
  END IF;

  UPDATE public.plaintes_en_cours
     SET data = (v_a || jsonb_build_object(
           'status', 'jugee',
           'verdict', 'condamnation',
           'juge', v_j.nom,
           'juge_le', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
           'jugement_jour', v_jour,
           'jugement_jour_pays', v_jour_pays,
           'appel_jusqu_au_jour', v_jour_pays + public.justice_fenetre_appel_jours(),
           'qualification_finale', v_calc ->> 'infraction',
           'qualification_libelle', v_libelle,
           'peine_genre', p_genre,
           'peine_jours', v_jours,
           'peine_amende', v_amende,
           'peine_libelle', v_peine,
           'detention_id', v_exec ->> 'detention_id'))::text
   WHERE id = p_affaire_id;

  PERFORM public.dossier_acte_consigner(p_affaire_id, v_pays, v_ville, 'condamnation',
    v_j.nom, 'juge', v_parquet, v_calc ->> 'infraction',
    jsonb_build_object('accuse', v_a ->> 'cible', 'genre', p_genre,
                       'jours', v_jours, 'amende', v_amende,
                       'jours_reference', (v_calc ->> 'jours_reference')::integer,
                       'executee', v_executee, 'instance', 'premiere'));

  RETURN jsonb_build_object('ok', true, 'jugement_id', v_jug, 'affaire', p_affaire_id,
    'juge', v_j.nom, 'jour', v_jour, 'jugement_cree', true,
    'infraction', v_calc ->> 'infraction', 'infraction_libelle', v_libelle,
    'qualification_parquet', v_parquet,
    'requalifiee', (v_parquet IS NOT NULL AND (v_calc ->> 'infraction') IS DISTINCT FROM v_parquet),
    'genre', p_genre, 'jours', v_jours, 'amende', v_amende, 'peine', v_peine,
    'motifs', v_motifs, 'executee', v_executee,
    'detention_id', v_exec ->> 'detention_id',
    'appel_jusqu_au_jour', v_jour_pays + public.justice_fenetre_appel_jours());
END;
$function$

CREATE OR REPLACE FUNCTION public.logement_info_interne(p_pays text, p_ville text, p_batiment text, p_piece text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_base text := p_piece; v_ch integer := 0; m text[]; h public.logements_sociaux_historiques;
  v_bail jsonb; v_id text; v_coloc text; v_reprise text; v_type text;
BEGIN
  IF p_pays IS NULL OR p_ville IS NULL OR p_batiment IS NULL OR p_piece IS NULL THEN RETURN NULL; END IF;
  m := regexp_match(p_piece, '^(.+)_chambre_([12])$');
  IF m IS NOT NULL THEN v_base := m[1]; v_ch := m[2]::integer; END IF;
  SELECT * INTO h FROM public.logements_sociaux_historiques x
   WHERE x.pays = p_pays AND x.ville = p_ville AND x.batiment = p_batiment AND x.piece = v_base;
  v_id := p_pays || ':' || p_batiment || ':' || v_base || ':' || p_ville;
  SELECT l.data INTO v_bail FROM public.locations_actives l WHERE l.id = v_id;
  IF h.piece IS NULL AND coalesce(v_bail->>'logementSocial', '') <> 'true' THEN RETURN NULL; END IF;
  /* premium_tous_logements_v1 : chambres aussi dans les logements construits en cours de partie */
  IF v_ch > 0 AND NOT public.logement_premium_possible_interne(p_batiment) THEN RETURN NULL; END IF;
  v_type := coalesce(nullif(v_bail->>'typeLogement', ''), h.type_logement, nullif(v_bail->>'type', ''), 'petit');
  IF v_ch > (CASE WHEN v_type = 'grand' THEN 2 ELSE 1 END) THEN RETURN NULL; END IF;
  SELECT c.colocataire INTO v_coloc FROM public.logements_colocations c WHERE c.bail_id = v_id;
  SELECT r.colocataire INTO v_reprise FROM public.logements_reprises r
   WHERE r.bail_id = v_id AND r.statut = 'en_attente' AND r.expire_le > now();
  RETURN jsonb_build_object('bail', v_id, 'pays', p_pays, 'ville', p_ville, 'batiment', p_batiment,
    'base', v_base, 'chambre', v_ch, 'type', v_type,
    'titulaire', nullif(replace(coalesce(v_bail->>'locataire', ''), 'pj:', ''), ''),
    'colocataire', v_coloc, 'reprise', v_reprise,
    'premium', EXISTS (SELECT 1 FROM public.logements_premium p
                        WHERE p.pays = p_pays AND p.ville = p_ville AND p.batiment = p_batiment AND p.piece = v_base),
    'premium_possible', public.logement_premium_possible_interne(p_batiment),
    'moral', coalesce(nullif(v_bail->>'bonusMoralSommeil', '')::integer, h.bonus_moral, 0),
    'sante', coalesce(nullif(v_bail->>'bonusSanteSommeil', '')::integer, h.bonus_sante, 0),
    'label', coalesce(v_bail->>'localLabel', h.label, v_base));
END $function$

CREATE OR REPLACE FUNCTION public.logement_jouissance_interne(p_acteur text, p_pays text, p_ville text, p_batiment text, p_piece text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE i jsonb; r text; ch integer;
BEGIN
  i := public.logement_info_interne(p_pays, p_ville, p_batiment, p_piece);
  IF i IS NULL THEN RETURN false; END IF;
  r := public.logement_role_interne(p_acteur, i);
  IF r IS NULL THEN RETURN false; END IF;
  ch := (i->>'chambre')::integer;
  IF ch = 0 THEN RETURN true; END IF;
  IF NOT (i->>'premium')::boolean THEN RETURN false; END IF;
  IF ch = 2 AND coalesce(i->>'colocataire', i->>'reprise') IS NOT NULL THEN RETURN r IN ('colocataire', 'reprise'); END IF;
  RETURN r IN ('titulaire', 'conjoint');
END $function$

CREATE OR REPLACE FUNCTION public.logement_sommeil_interne(p_acteur text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d record; i jsonb; r text; v_medaille boolean;
BEGIN
  SELECT country, current_city, current_building, current_room INTO d FROM public.personnages_donnees WHERE name = p_acteur;
  i := public.logement_info_interne(d.country, d.current_city, d.current_building, d.current_room);
  IF i IS NULL THEN RETURN NULL; END IF;
  r := public.logement_role_interne(p_acteur, i);
  IF r IS NULL OR r = 'reprise' THEN RETURN NULL; END IF;
  IF (i->>'premium')::boolean THEN
    IF (i->>'chambre')::integer = 0 THEN RETURN NULL; END IF;
  ELSIF (i->>'chambre')::integer <> 0 THEN RETURN NULL; END IF;
  -- heros_travail_medaille_v1 (13/11/2026) : médaille installée dans le logement (salon ou chambre).
  v_medaille := EXISTS (SELECT 1 FROM public.equipements_installes e
    WHERE e.generique_id = 'medaille_heros_travail' AND e.pays = d.country AND e.ville = d.current_city
      AND e.batiment = d.current_building AND (e.piece = i->>'base' OR e.piece LIKE (i->>'base') || '\_chambre\_%'));
  RETURN jsonb_build_object('pa', 1, 'moral', (i->>'moral')::integer + CASE WHEN v_medaille THEN 3 ELSE 0 END,
    'sante', (i->>'sante')::integer, 'role', r, 'premium', (i->>'premium')::boolean, 'label', i->>'label',
    'medaille', v_medaille);
END $function$

CREATE OR REPLACE FUNCTION public.mail_systeme_poser_interne(p_expediteur text, p_destinataire text, p_sujet text, p_corps text, p_heure text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id text; v_etat text; v_msg text;
BEGIN
  IF coalesce(btrim(p_expediteur),'') = '' OR coalesce(btrim(p_destinataire),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'parametres_invalides');
  END IF;

  v_id := 'mail-' || (extract(epoch from clock_timestamp())*1000)::bigint
                  || '-' || substr(md5(random()::text), 1, 6);

  -- UNE NOTIFICATION N'EST PAS L'AUTORITE DE L'ACTE (doctrine du 9 octobre 2026). Cet INSERT est
  -- enferme dans son propre bloc : une erreur ici ne doit PAS annuler l'operation metier de
  -- l'appelant, qui est peut-etre une arrestation, une saisie ou une nomination deja acquise.
  -- Une RPC etant une seule transaction, une exception non rattrapee emportait tout.
  --
  -- MAIS L'ECHEC N'EST PAS AVALE : il est consigne avec son SQLSTATE et son message. Le courrier
  -- perdu est donc nommable, et le verdict rendu dit ok=false.
  BEGIN
    INSERT INTO public.mails (id, from_player, to_player, subject, body, time, read)
    VALUES (v_id, p_expediteur, p_destinataire, p_sujet, p_corps,
            coalesce(p_heure, to_char(now() AT TIME ZONE 'Europe/Paris', 'HH24') || 'h'), false);
  EXCEPTION WHEN others THEN
    GET STACKED DIAGNOSTICS v_etat = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    INSERT INTO public.mails_envois_systeme (auteur_reel, expediteur, destinataire, sujet, echec)
    VALUES (public.mon_personnage(), p_expediteur, p_destinataire, left(coalesce(p_sujet,''),200),
            v_etat || ' ' || left(coalesce(v_msg,''), 300));
    RETURN jsonb_build_object('ok', false, 'raison', 'envoi_impossible', 'sqlstate', v_etat);
  END;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END; $function$

CREATE OR REPLACE FUNCTION public.navigation_disponibilite_interne(p_nom text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p public.personnages_donnees%ROWTYPE;
BEGIN
 SELECT * INTO p FROM public.personnages_donnees WHERE name=p_nom FOR UPDATE;
 IF NOT FOUND OR (p.est_emprisonne IS NOT NULL AND p.est_emprisonne<>'null'::jsonb) THEN
  RETURN jsonb_build_object('ok',false,'raison','personnage_indisponible'); END IF;
 IF EXISTS(SELECT 1 FROM public.police_interceptions WHERE personnage=p_nom AND expires_at>now()) THEN
  RETURN jsonb_build_object('ok',false,'raison','interception_en_cours'); END IF;
 IF EXISTS(SELECT 1 FROM public.batailles_engagements e JOIN public.batailles b ON b.id=e.bataille_id
  WHERE e.personnage=p_nom AND e.sorti_round IS NULL AND b.statut='en_cours') THEN
  RETURN jsonb_build_object('ok',false,'raison','combat_en_cours'); END IF;
 IF coalesce(p.hp,100)<=0
 OR coalesce(p.hospitalisation->>'dateFinParis','')>(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date::text
 OR (CASE WHEN coalesce(p.hospitalisation->>'jourFin','')~'^[0-9]+$'
 THEN (p.hospitalisation->>'jourFin')::numeric>coalesce(p.day,1) ELSE false END) THEN
  RETURN jsonb_build_object('ok',false,'raison','acteur_incapacite'); END IF;
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.navigation_interieure_personnage_interne(p_nom text, p_batiment text, p_piece text, p_verifier boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p public.personnages_donnees%ROWTYPE;l public.navigation_lieux_regles%ROWTYPE;r jsonb; total numeric;
BEGIN
 r:=public.navigation_disponibilite_interne(p_nom);
 IF NOT coalesce((r->>'ok')::boolean,false) THEN RETURN r; END IF;
 SELECT * INTO p FROM public.personnages_donnees WHERE name=p_nom;
 -- navigation_zone_speciale_v1
 IF p_batiment IS NULL AND p_piece IS NULL AND (p.current_city,p.current_building) IN (('caserne','caserne-militaire'),('qhs','qhs-prison')) THEN IF NOT p_verifier THEN UPDATE public.personnages_donnees SET current_building=NULL,current_room=NULL,current_street=NULL,updated_at=clock_timestamp() WHERE name=p_nom;END IF; RETURN jsonb_build_object('ok',true,'building',NULL,'room',NULL);END IF;
 SELECT * INTO l FROM public.navigation_lieux_regles WHERE pays=p.country AND ville=p.current_city AND batiment=p_batiment;
 IF NOT public.navigation_piece_referencee_interne(p.country,p.current_city,p_batiment,p_piece) THEN RETURN jsonb_build_object('ok',false,'raison','destination_inconnue'); END IF;
 IF p_batiment='quartier-ambassades' AND p_piece IN ('bureau_al_khalija','bureau_sovarka','bureau_el_estado') THEN
  r:=public.ambassade_acces_bureau_interne(CASE p_piece WHEN 'bureau_al_khalija' THEN 'khalija' WHEN 'bureau_sovarka' THEN 'soviet' ELSE 'narco' END,p_nom);
  IF NOT coalesce((r->>'ok')::boolean,false) THEN RETURN r; END IF;
 END IF;
 -- palais_ambassades_novomirsk_audience_v1 : même autorité serveur qu'à Luthécia.
 IF p.country='soviet' AND p.current_city='capitale' AND p_batiment='palais-ambassades-novomirsk'
    AND p_piece IN ('bureau_republia_novomirsk','bureau_khalija_novomirsk','bureau_estado_novomirsk') THEN
  r:=public.ambassade_acces_bureau_interne(CASE p_piece
        WHEN 'bureau_republia_novomirsk' THEN 'republic'
        WHEN 'bureau_khalija_novomirsk' THEN 'khalija'
        ELSE 'narco' END,p_nom);
  IF NOT coalesce((r->>'ok')::boolean,false) THEN RETURN r; END IF;
 END IF;
 -- palais_presidentiel_sovarka_v1 (Fred, 08/11/2026) : restaurant et appartements groupé au président, musée sur billet du jour.
 IF p.country='soviet' AND p.current_city='capitale' AND p_batiment='palais-presidentiel' AND (p.current_building IS DISTINCT FROM p_batiment OR p.current_room IS DISTINCT FROM p_piece) THEN
  r:=CASE WHEN public.sovarka_palais_acces_interne(p_nom,p_piece) IS NULL THEN NULL ELSE jsonb_build_object('ok',false,'raison',public.sovarka_palais_acces_interne(p_nom,p_piece),'membre',p_nom) END;
  IF r IS NOT NULL THEN RETURN r; END IF;
 END IF;
 -- acces_reserve_v1 (Fred, 12/11/2026) : Pavillon des Ambassadeurs et Résidence impériale de Novomirsk.
 IF p.country='soviet' AND p.current_city='capitale' AND p_batiment IN ('pavillon-ambassadeurs-novomirsk','residence-imperiale-novomirsk') THEN
  IF p.current_building IS DISTINCT FROM p_batiment AND NOT p_verifier THEN DELETE FROM public.acces_intrusions WHERE acteur=p_nom AND batiment=p_batiment; END IF;
  IF p.current_building IS DISTINCT FROM p_batiment OR p.current_room IS DISTINCT FROM p_piece THEN
   r:=CASE WHEN public.acces_reserve_raison_interne(p_nom,p_batiment,p_piece) IS NULL THEN NULL
      ELSE jsonb_build_object('ok',false,'raison',public.acces_reserve_raison_interne(p_nom,p_batiment,p_piece),'batiment',p_batiment,'piece',p_piece,'membre',p_nom) END;
   IF r IS NOT NULL THEN RETURN r; END IF;
  END IF;
 END IF;
 -- ssm_acces_sur_rendezvous_v1
 IF p.country='republic' AND p.current_city='ville_b' AND p_batiment='services-sociaux-montrouge' AND p_piece='bureau_assistante_sociale' AND NOT public.ssm_rendezvous_valide_interne(p_nom) THEN RETURN jsonb_build_object('ok',false,'raison','rendezvous_ssm_requis'); END IF;
 IF l.ferme THEN RETURN jsonb_build_object('ok',false,'raison','acces_restreint'); END IF;
 -- Les restrictions sans porte serveur pour une identité arbitraire restent
 -- fermées, jamais déduites d'un cache ou d'une attestation du navigateur.
 IF l.membership='loge' AND NOT EXISTS(
   SELECT 1 FROM public.organisations o
   WHERE o.data::jsonb->>'type'='loge' AND o.data::jsonb->>'statut'='actif'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.data::jsonb->'membres')='array'
       THEN o.data::jsonb->'membres' ELSE '[]'::jsonb END) m WHERE m->>'nom'=p_nom)) THEN
  RETURN jsonb_build_object('ok',false,'raison','membre_loge_requis'); END IF;
 IF p_batiment='clinique-privee' AND p_piece~'^chambre_([1-9]|10)$' AND EXISTS(
   SELECT 1 FROM public.locations_actives loc WHERE loc.country=p.country
   AND loc.data->>'buildingId'=p_batiment AND loc.data->>'roomId'=p_piece AND loc.data->>'city'='capitale'
   AND loc.data->>'locataire' IS DISTINCT FROM p_nom AND loc.data->'visitesAutorisees'='false'::jsonb) THEN
  RETURN jsonb_build_object('ok',false,'raison','visite_refusee'); END IF;
 IF (l.membership IS NOT NULL AND l.membership<>'loge') 
 /* navigation_acces_ambassade_par_membre_v1 */ THEN
  RETURN jsonb_build_object('ok',false,'raison','acces_collectif_a_raccorder'); END IF;
 -- douane_zone_par_membre_v1
 IF p_piece='zone_embarquement' AND NOT public.douane_passage_valide_interne(p_nom,'avion') THEN
 RETURN jsonb_build_object('ok',false,'raison','controle_douanier_requis');END IF;
 -- serrure_batiment_v1 (04/11/2026) : un batiment ferme a cle ne s'ouvre qu'a qui en detient une cle.
 IF p.current_building IS DISTINCT FROM p_batiment
    AND public.serrure_batiment_ferme_interne(p_nom, p.country, p.current_city, p_batiment) THEN
  RETURN jsonb_build_object('ok',false,'raison','porte_fermee_a_cle','batiment',true); END IF;
 -- serrure_porte_v1 (04/11/2026) : un lieu ferme a cle ne s'ouvre qu'a qui en detient une cle.
 IF (p.current_building IS DISTINCT FROM p_batiment OR p.current_room IS DISTINCT FROM p_piece)
    AND public.serrure_porte_fermee_interne(p_nom, p.country, p.current_city, p_batiment, p_piece) THEN
  RETURN jsonb_build_object('ok',false,'raison','porte_fermee_a_cle'); END IF;
 -- blocus_syndical_v1
 IF p_batiment IS NOT NULL AND p_piece IS DISTINCT FROM (l.pieces->>0) AND public.blocus_actif_interne(p.country,p.current_city,p_batiment) IS NOT NULL THEN
  RETURN jsonb_build_object('ok',false,'raison','blocus_syndical'); END IF;
 IF EXISTS(SELECT 1 FROM public.batiments_fermes f WHERE f.pays=p.country AND f.ville=p.current_city AND f.batiment_id=p_batiment
 AND (f.date_fin_universelle>(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date
 OR (f.date_fin_universelle IS NULL AND f.jour_fin>p.day))) THEN
  RETURN jsonb_build_object('ok',false,'raison','batiment_ferme'); END IF;
 IF p.current_building IS DISTINCT FROM p_batiment THEN
  IF p.current_building IS NOT NULL OR (NOT EXISTS(SELECT 1 FROM public.rue_sorties_batiments
   WHERE country=p.country AND city=p.current_city AND building=p_batiment AND noeud=p.current_street) AND NOT (p.current_street IS NULL AND (p.current_city,p_batiment,p_piece) IN (('caserne','caserne-militaire','corps_garde'),('qhs','qhs-prison','entree_qhs')))) THEN
   RETURN jsonb_build_object('ok',false,'raison','entree_non_accessible'); END IF;
  SELECT coalesce(sum(coalesce(nullif(x->>'qty','')::numeric,nullif(x->>'encombrement','')::numeric,1)),0)
   INTO total FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p.inventory)='array' THEN p.inventory ELSE '[]'::jsonb END) x;
  IF total>100 THEN RETURN jsonb_build_object('ok',false,'raison','inventaire_surcharge'); END IF;
 END IF;
 IF NOT p_verifier AND (p.current_building IS DISTINCT FROM p_batiment OR p.current_room IS DISTINCT FROM p_piece) THEN
  UPDATE public.personnages_donnees SET current_building=p_batiment,current_room=p_piece,current_street=NULL,updated_at=clock_timestamp() WHERE name=p_nom;
 END IF;
 RETURN jsonb_build_object('ok',true,'building',p_batiment,'room',p_piece);
END $function$

CREATE OR REPLACE FUNCTION public.pa_repos_nocturne(p_acteur text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_pa_max         constant integer := 30;
  c_gain_civil     constant integer := 12;
  c_gain_caserne   constant integer := 12;
  c_gain_terrain   constant integer := 8;
  c_bonus_tente    constant integer := 2;
  v_pa integer; v_qhs jsonb; v_bonus integer; v_deja date;
  v_jour date := (now() AT TIME ZONE 'Europe/Paris')::date;
  v_nouveau integer; v_plafond_qhs integer;
  v_caserne boolean; v_tente boolean; v_grade text; v_gain integer;
  v_hosp jsonb; v_logement jsonb; v_j integer; v_repas integer; v_detenu jsonb; v_prison boolean := false;
BEGIN
  PERFORM public.exiger_acteur(p_acteur);
  SELECT coalesce(pa, 0), detention_qhs, coalesce(bonus_pa_differe, 0), pa_repos_le,
         coalesce(current_building, '') = 'caserne-militaire',
         EXISTS (SELECT 1 FROM jsonb_array_elements(
                   CASE WHEN jsonb_typeof(d.inventory) = 'array' THEN d.inventory ELSE '[]'::jsonb END) i
                  WHERE i->>'produitMilitaire' = 'tente')
    INTO v_pa, v_qhs, v_bonus, v_deja, v_caserne, v_tente
    FROM public.personnages_donnees d WHERE d.name = p_acteur FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable');
  END IF;
  IF v_deja IS NOT NULL AND v_deja >= v_jour THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'deja_repose', 'pa', v_pa);
  END IF;

  -- hospitalisation_pa0_repos_v2 (GAME-DESIGN-HOSPITALISATION.md, Fred 01/11/2026)
  SELECT hospitalisation, est_emprisonne INTO v_hosp, v_detenu FROM public.personnages_donnees WHERE name = p_acteur;
  v_j := public.hospitalisation_jour_pa0(v_hosp);
  IF v_j IS NOT NULL THEN
    IF v_j <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'hospitalise_j0', 'pa', v_pa);
    END IF;
    v_gain := (CASE v_j WHEN 1 THEN 2 WHEN 2 THEN 6 ELSE 12 END)
            * (CASE WHEN v_hosp ->> 'lieu' = 'clinique' THEN 3 ELSE 1 END);
    v_repas := CASE WHEN v_hosp ->> 'repasLe' = (v_jour - 1)::text
               THEN coalesce((v_hosp ->> 'repasBonus')::integer, 2) ELSE 0 END;
    v_nouveau := least(c_pa_max, greatest(0, v_pa + v_gain + v_repas + v_bonus));
    UPDATE public.personnages_donnees
       SET pa = v_nouveau, bonus_pa_differe = 0, pa_repos_le = v_jour
     WHERE name = p_acteur;
    -- Rébellion : après ce premier sommeil, retour dans la cellule retenue à l'arrestation.
    IF (v_hosp ->> 'detention')::boolean IS TRUE THEN
      IF v_detenu IS NOT NULL AND v_detenu <> 'null'::jsonb AND jsonb_typeof(v_hosp -> 'cellule') = 'object' THEN
        UPDATE public.personnages_donnees
           SET country = v_hosp #>> '{cellule,country}', current_city = v_hosp #>> '{cellule,city}',
               current_building = v_hosp #>> '{cellule,building}', current_room = v_hosp #>> '{cellule,room}',
               current_street = NULL, hospitalisation = NULL,
               est_emprisonne = est_emprisonne || jsonb_build_object('rebellion', true),
               updated_at = clock_timestamp()
         WHERE name = p_acteur;
        v_prison := true;
      ELSE
        -- Libéré entre-temps : il reste un patient ordinaire.
        UPDATE public.personnages_donnees SET hospitalisation = hospitalisation - 'detention' - 'cellule'
         WHERE name = p_acteur;
      END IF;
    END IF;
    RETURN jsonb_build_object('ok', true, 'pa', v_nouveau, 'bonus_consomme', v_bonus,
      'qhs', false, 'hospitalisation', true, 'jour_hospitalisation', v_j,
      'lieu', v_hosp ->> 'lieu', 'gain', v_gain, 'repas', v_repas,
      'transfert_prison', v_prison,
      'sortie_possible', NOT v_prison AND v_j >= 2 AND v_nouveau >= 20);
  END IF;

  IF v_qhs IS NOT NULL AND jsonb_typeof(v_qhs) = 'object' AND (v_qhs ->> 'enQHS')::boolean IS TRUE THEN
    v_plafond_qhs := CASE WHEN (v_qhs ->> 'paLimite1Jour')::boolean IS TRUE THEN 1 ELSE 3 END;
    v_nouveau := least(c_pa_max, greatest(0, v_plafond_qhs + v_bonus));
    IF (v_qhs ->> 'paLimite1Jour')::boolean IS TRUE THEN
      UPDATE public.personnages_donnees
         SET detention_qhs = v_qhs || jsonb_build_object('paLimite1Jour', false)
       WHERE name = p_acteur;
    END IF;
  ELSE
    v_grade := public.militaire_grade_effectif(p_acteur);
    IF v_grade IS NULL THEN
      v_gain := c_gain_civil;
    ELSIF v_caserne THEN
      v_gain := c_gain_caserne;
    ELSIF v_tente THEN
      v_gain := c_gain_terrain + c_bonus_tente;
    ELSE
      v_gain := c_gain_terrain;
    END IF;
    -- detention_rebellion_repos_v1
    IF v_detenu IS NOT NULL AND v_detenu <> 'null'::jsonb AND (v_detenu ->> 'rebellion')::boolean IS TRUE THEN
      v_gain := 4;
    END IF;
    -- palais_presidentiel_repos_v1 (Fred, 08/11/2026) : +1 PA au président de Sovarka qui dort dans ses appartements.
    IF EXISTS (SELECT 1 FROM public.personnages_donnees WHERE name = p_acteur AND country = 'soviet' AND current_city = 'capitale'
                 AND current_building = 'palais-presidentiel' AND current_room = 'appartements_president')
       AND EXISTS (SELECT 1 FROM public.cycles_electoraux WHERE id = 'soviet_president' AND data::jsonb ->> 'eluId' = p_acteur) THEN
      v_gain := v_gain + 1;
    END IF;
    -- Bail diplomatique actif du Pavillon : bonus au repos autorisé, une seule fois/jour.
    IF EXISTS (SELECT 1 FROM public.pavillon_baux pb
      WHERE pb.locataire=p_acteur AND pb.statut='actif' AND pb.debut<=v_jour AND pb.fin_excl>v_jour)
    THEN v_gain := v_gain + 3; END IF;
    -- residence_imperiale_v1 : nuit passée dans son appartement loué de la Résidence impériale.
    -- appartements_populaires_repos_v1 (Fred, 12/11/2026) : +1 PA dans son appartement populaire.
    v_logement := public.logement_sommeil_interne(p_acteur);
    IF v_logement IS NOT NULL THEN v_gain := v_gain + coalesce((v_logement->>'pa')::integer, 0); END IF;
    PERFORM public.residence_bonus_nuit_interne(p_acteur);
    -- escort_piratage_v1 : un escort sous contrat peut copier un dossier pendant la nuit.
    PERFORM public.escort_piratage_nuit_interne(p_acteur);
    v_nouveau := least(c_pa_max, greatest(0, v_pa + v_gain + v_bonus));
  END IF;

  UPDATE public.personnages_donnees
     SET pa = v_nouveau, bonus_pa_differe = 0, pa_repos_le = v_jour
   WHERE name = p_acteur;

  RETURN jsonb_build_object('ok', true, 'pa', v_nouveau, 'bonus_consomme', v_bonus,
                            'qhs', (v_qhs ->> 'enQHS')::boolean IS TRUE,
                            'grade_militaire', v_grade, 'gain', v_gain,
                            'caserne', v_caserne, 'tente', v_tente, 'logement', v_logement);
END;
$function$

CREATE OR REPLACE FUNCTION public.payer_ordre_interne(p_acteur text, p_fn text, p_pa integer, p_cost integer, p_quantite integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_fn text := coalesce(nullif(btrim(coalesce(p_fn,'')), ''), '(non transmis)');
  v_acquisition boolean;
  v_connu boolean; v_valide boolean;
  v_pa integer; v_liquide numeric; v_arg numeric;
  v_compte_id text; v_solde numeric := 0;
  v_pris_liquide numeric; v_pris_national numeric;
  v_memorable record; v_pays text;
BEGIN
  IF v_fn='louer_lot_ici' THEN RETURN jsonb_build_object('ok',false,'raison','commande_versionnee_requise');END IF;
  IF v_fn = 'deposer_demande_permis' AND NOT EXISTS (
    SELECT 1 FROM public.permis_transactions_internes WHERE transaction_id=txid_current() AND acteur=auth.uid()
  ) THEN RETURN jsonb_build_object('ok',false,'raison','commande_versionnee_requise'); END IF;
  PERFORM public.exiger_acteur(p_acteur);
  IF public.blocus_ordre_refuse_interne(p_acteur, v_fn) THEN -- blocus_syndical_v1
    RETURN jsonb_build_object('ok', false, 'raison', 'blocus_syndical', 'fn', v_fn);
  END IF;
  v_acquisition:=EXISTS(SELECT 1 FROM public.acquisitions_transactions_internes a WHERE a.transaction_id=txid_current() AND a.acteur=p_acteur AND ((a.ordre=v_fn AND a.pa=p_pa AND a.montant=p_cost) OR (a.ordre='signer_compromis' AND v_fn='deposer_demande_permis' AND p_pa=0 AND p_cost=0)));
  IF v_fn IN('acheter_terrain','signer_compromis','acte_vente_terrain','emprunter') AND NOT v_acquisition THEN RETURN jsonb_build_object('ok',false,'raison','commande_versionnee_requise');END IF;
  IF coalesce(p_pa, 0) < 0 OR coalesce(p_cost, 0) < 0 THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'montant_negatif');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.ordres_couts o WHERE o.fn = v_fn) INTO v_connu;

  IF NOT v_connu AND NOT v_acquisition THEN
    INSERT INTO public.ordres_couts_inconnus (fn, pa, cost)
    VALUES (v_fn, coalesce(p_pa,0), coalesce(p_cost,0))
    ON CONFLICT (fn) DO UPDATE SET occurrences = public.ordres_couts_inconnus.occurrences + 1;
    RETURN jsonb_build_object('ok', false, 'raison', 'ordre_inconnu', 'fn', v_fn);
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.ordres_couts o
                 WHERE o.fn = v_fn AND o.pa = coalesce(p_pa,0) AND o.cost = coalesce(p_cost,0))
    INTO v_valide;
  -- sovarka_tarifs_nationaux_v1 : tarif national du pays du joueur, seul valable s'il existe.
  IF EXISTS (SELECT 1 FROM public.ordres_couts_pays o JOIN public.personnages_donnees d
               ON d.name = p_acteur AND d.country = o.pays WHERE o.fn = v_fn) THEN
    v_valide := EXISTS (SELECT 1 FROM public.ordres_couts_pays o JOIN public.personnages_donnees d
               ON d.name = p_acteur AND d.country = o.pays
               WHERE o.fn = v_fn AND o.pa = coalesce(p_pa,0) AND o.cost = coalesce(p_cost,0));
  END IF;
  IF NOT v_valide AND NOT v_acquisition THEN
    INSERT INTO public.ordres_couts_ecarts (fn, pa, cost)
    VALUES (v_fn, coalesce(p_pa,0), coalesce(p_cost,0))
    ON CONFLICT (fn, pa, cost)
      DO UPDATE SET occurrences = public.ordres_couts_ecarts.occurrences + 1, vu_le = now();
    RETURN jsonb_build_object('ok', false, 'raison', 'cout_non_declare',
                              'fn', v_fn, 'pa', p_pa, 'cost', p_cost);
  END IF;


  IF p_quantite IS NULL OR p_quantite<1 OR coalesce(p_cost,0)::bigint*p_quantite>2147483647 THEN
    RETURN jsonb_build_object('ok',false,'raison','quantite_de_paiement_invalide'); END IF;
  p_cost:=coalesce(p_cost,0)*p_quantite;
  SELECT pa, liquide, arg INTO v_pa, v_liquide, v_arg
  FROM public.personnages_donnees WHERE name = p_acteur FOR UPDATE;
  IF v_pa IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable');
  END IF;

  SELECT id, solde INTO v_compte_id, v_solde FROM public.comptes_bancaires
  WHERE personnage = p_acteur AND banque = 'nationale' FOR UPDATE;
  v_solde := coalesce(v_solde, 0);

  IF v_pa < coalesce(p_pa, 0) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'pa_insuffisants', 'pa_reel', v_pa);
  END IF;
  IF coalesce(v_liquide,0) + v_solde < coalesce(p_cost, 0) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'fonds_insuffisants',
                              'disponible', coalesce(v_liquide,0) + v_solde);
  END IF;

  v_pris_liquide := least(coalesce(v_liquide,0), coalesce(p_cost,0));
  v_pris_national := coalesce(p_cost,0) - v_pris_liquide;

  UPDATE public.personnages_donnees
     SET pa = v_pa - coalesce(p_pa,0),
         liquide = coalesce(v_liquide,0) - v_pris_liquide,
         arg = coalesce(v_arg,0) - coalesce(p_cost,0)
   WHERE name = p_acteur;

  IF v_pris_national > 0 AND v_compte_id IS NOT NULL THEN
    UPDATE public.comptes_bancaires SET solde = solde - v_pris_national,
           updated_at = now() WHERE id = v_compte_id;
  END IF;

  -- LA MEMOIRE DES MANDATS (11 octobre 2026). Apres le prelevement, donc sur un fait accompli, et
  -- seulement si le triplet figure au registre des actes memorables. `presidence_memoire_noter`
  -- verifie elle-meme que l'acteur est bien le President en exercice : si c'est un ministre qui
  -- tient la conference de presse, rien n'est ecrit. Le registre ne contient AUCUN panneau a
  -- (0 PA, 0 FR) -- ouvrir une fenetre n'est pas un acte.
  SELECT * INTO v_memorable FROM public.presidence_memoire_ordres
   WHERE fn = v_fn AND pa = coalesce(p_pa,0) AND cost = coalesce(p_cost,0);
  IF FOUND THEN
    SELECT country INTO v_pays FROM public.personnages_donnees WHERE name = p_acteur;
    PERFORM public.presidence_memoire_noter(
      v_pays, 'reaction', 'ordre_presidentiel', v_memorable.sujet,
      jsonb_build_object('ordre', v_fn, 'pa', coalesce(p_pa,0), 'cout', coalesce(p_cost,0)),
      p_acteur);
  END IF;

  -- FONDS EN TRANSIT (26/10/2026) : ce que le navigateur vient de payer pourra etre verse a une
  -- caisse par lui, et rien d'autre. Seulement pour un paiement demande directement par le navigateur.
  IF coalesce(p_cost, 0) > 0 AND coalesce(current_setting('request.path', true), '') = '/rpc/payer_ordre' THEN
    PERFORM public.fonds_transit_deposer_interne(p_acteur, p_cost, 'ordre:' || v_fn);
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'pa', v_pa - coalesce(p_pa,0),
    'liquide', coalesce(v_liquide,0) - v_pris_liquide,
    'arg', coalesce(v_arg,0) - coalesce(p_cost,0),
    'solde_national', v_solde - v_pris_national,
    'pa_preleves', coalesce(p_pa,0), 'montant_preleve', coalesce(p_cost,0));
END;
$function$

CREATE OR REPLACE FUNCTION public.pnj_groupes_projeter_institutions_interne(p_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b record; etat jsonb; suivant jsonb; liste jsonb; cle text; agents text; valeur jsonb;
BEGIN
 -- projections_etats_pnj_v2
 FOR b IN SELECT DISTINCT t.id,t.country,t.city,t.building_id FROM public.batiments_etat t
  JOIN public.pnj_membres m ON m.pays=t.country
   AND m.proprietaire_perimetre=t.city||':'||t.building_id
  WHERE m.id=ANY(p_ids) AND m.proprietaire_institution IN ('police','douane')
   AND m.famille IN ('policier','douanier') ORDER BY t.id LOOP
  SELECT data INTO valeur FROM public.batiments_etat WHERE id=b.id FOR UPDATE;
  etat:=public.batiment_etat_lire(valeur);
  IF jsonb_typeof(etat) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'projection_service_etat_invalide'; END IF;
  cle:=CASE WHEN b.building_id IN ('commissariat','commissariat-local') THEN 'effectifsPolice' ELSE 'effectifsDouane' END;
  agents:=CASE WHEN cle='effectifsPolice' THEN 'policiers' ELSE 'douaniers' END;
  IF jsonb_typeof(etat->cle->agents) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'projection_service_liste_invalide'; END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN m.id IS NULL THEN d.objet
    ELSE d.objet||jsonb_build_object('pa',CASE WHEN m.statut='actif' THEN m.pa ELSE 0 END,'statut',m.statut,'buildingId',pe.building_id,'roomId',pe.room_id,
      'rueNoeudId',CASE WHEN pe.building_id IS NULL THEN pe.rue_noeud_id ELSE NULL END) END ORDER BY d.rang),'[]'::jsonb) INTO liste
   FROM jsonb_array_elements(etat->cle->agents) WITH ORDINALITY d(objet,rang)
   LEFT JOIN public.pnj_membres m ON m.id=CASE WHEN cle='effectifsPolice'
    THEN public.police_pnj_id(b.country,b.city,d.objet->>'matricule')
    ELSE public.douane_pnj_id(b.country,b.city,d.objet->>'matricule') END
   LEFT JOIN LATERAL public.pnj_position_effective(m.id) pe ON true WHERE m.id IS NULL OR m.statut<>'mort';
  suivant:=jsonb_set(etat,ARRAY[cle,agents],liste,false);
  -- Conserver le format historique (objet ou chaîne JSON), les PA et tous les autres champs.
  suivant:=CASE WHEN jsonb_typeof(valeur)='string' THEN to_jsonb(suivant::text) ELSE suivant END;
  -- Cette condition termine la récursion du trigger de miroir après un seul rapprochement.
  UPDATE public.batiments_etat SET data=suivant WHERE id=b.id AND data IS DISTINCT FROM suivant;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.presidence_memoire_noter(p_pays text, p_genre text, p_source text, p_sujet text, p_detail jsonb, p_acteur text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m record; s record; v_id bigint;
BEGIN
  IF coalesce(btrim(coalesce(p_pays,'')), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'enregistre', false, 'raison', 'pays_absent');
  END IF;

  SELECT * INTO s FROM public.presidence_memoire_sources WHERE source = p_source;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'enregistre', false, 'raison', 'source_non_declaree');
  END IF;
  IF s.genre IS DISTINCT FROM p_genre THEN
    RETURN jsonb_build_object('ok', false, 'enregistre', false, 'raison', 'genre_contredit_la_source',
                              'genre_declare', s.genre);
  END IF;

  SELECT * INTO m FROM public.presidence_mandat_courant(p_pays);
  IF NOT FOUND THEN
    -- AUCUN PRESIDENT JOUEUR : on n'ecrit rien, et ce n'est pas un echec. C'est l'etat de la beta
    -- au 11 octobre 2026, et c'est ce qui empeche de fabriquer un passe.
    RETURN jsonb_build_object('ok', true, 'enregistre', false, 'raison', 'aucun_president_joueur');
  END IF;

  IF p_genre = 'reaction' AND coalesce(p_acteur, '') IS DISTINCT FROM m.president THEN
    RETURN jsonb_build_object('ok', true, 'enregistre', false, 'raison', 'acteur_n_est_pas_le_president');
  END IF;

  INSERT INTO public.presidence_memoire (pays, president, mandat_depuis, genre, source, sujet, detail, jour)
  VALUES (p_pays, m.president, m.depuis, p_genre, p_source, p_sujet,
          coalesce(p_detail, '{}'::jsonb), public.jour_de_jeu_pays(p_pays))
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'enregistre', true, 'id', v_id,
                            'president', m.president, 'mandat_depuis', m.depuis);
END;
$function$

CREATE OR REPLACE FUNCTION public.recherche_inscrire(p_entree jsonb, p_cible text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_cible text; v_id text; v_apres jsonb; v_n integer;
BEGIN
  IF p_entree IS NULL OR jsonb_typeof(p_entree) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'entree_invalide');
  END IF;

  v_moi := public.mon_personnage();
  IF v_moi IS NOT NULL THEN
    -- UN JOUEUR N'INSCRIT QUE SUR SA PROPRE FICHE. Condamner autrui est un pouvoir, et il a sa
    -- porte : justice_condamner, qui relit le poste de l'appelant.
    IF p_cible IS NOT NULL AND p_cible <> v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_ma_fiche');
    END IF;
    v_cible := v_moi;
  ELSE
    IF coalesce(btrim(coalesce(p_cible, '')), '') = '' THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'cible_manquante');
    END IF;
    v_cible := p_cible;
  END IF;

  PERFORM set_config('rp.recherche_interne', 'on', true);

  -- IDEMPOTENCE PAR IDENTIFIANT, quand l'entree en porte un. C'est le cas du mandat d'arret des
  -- tracts calomnieux, dont le client verifiait deja l'absence avant de le refleter. Un crime
  -- ordinaire, lui, n'a pas d'identifiant : il peut etre commis deux fois, et doit s'inscrire
  -- deux fois.
  v_id := nullif(p_entree ->> 'id', '');
  IF v_id IS NOT NULL THEN
    SELECT count(*) INTO v_n FROM public.personnages_donnees d,
           jsonb_array_elements(CASE WHEN jsonb_typeof(d.recherche)='array'
                                     THEN d.recherche ELSE '[]'::jsonb END) e
     WHERE d.name = v_cible AND e ->> 'id' = v_id;
    IF v_n > 0 THEN
      SELECT coalesce(recherche, '[]'::jsonb) INTO v_apres
        FROM public.personnages_donnees WHERE name = v_cible;
      RETURN jsonb_build_object('ok', true, 'action', 'deja_inscrite',
                                'recherche', coalesce(v_apres, '[]'::jsonb));
    END IF;
  END IF;

  -- L'AJOUT EST ATOMIQUE : aucune relecture, donc aucune fenetre de perte.
  UPDATE public.personnages_donnees
     SET recherche = (CASE WHEN jsonb_typeof(recherche) = 'array'
                           THEN recherche ELSE '[]'::jsonb END) || jsonb_build_array(p_entree)
   WHERE name = v_cible
  RETURNING recherche INTO v_apres;
  PERFORM set_config('rp.recherche_interne', '', true);   -- la portee s'arrete ici
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable');
  END IF;

  RETURN jsonb_build_object('ok', true, 'action', 'inscrite',
                            'recherche', coalesce(v_apres, '[]'::jsonb));
END; $function$

CREATE OR REPLACE FUNCTION public.recherche_retirer_par_id(p_cible text, p_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_avant jsonb; v_apres jsonb;
BEGIN
  IF coalesce(btrim(coalesce(p_cible, '')), '') = ''
     OR coalesce(btrim(coalesce(p_id, '')), '') = '' THEN RETURN 0; END IF;

  SELECT CASE WHEN jsonb_typeof(recherche) = 'array' THEN recherche ELSE '[]'::jsonb END
    INTO v_avant FROM public.personnages_donnees WHERE name = p_cible FOR UPDATE;
  IF v_avant IS NULL THEN RETURN 0; END IF;

  SELECT coalesce(jsonb_agg(e), '[]'::jsonb) INTO v_apres
    FROM jsonb_array_elements(v_avant) e WHERE (e ->> 'id') IS DISTINCT FROM p_id;

  IF jsonb_array_length(v_apres) = jsonb_array_length(v_avant) THEN RETURN 0; END IF;
  PERFORM set_config('rp.recherche_interne', 'on', true);
  UPDATE public.personnages_donnees SET recherche = v_apres WHERE name = p_cible;
  PERFORM set_config('rp.recherche_interne', '', true);
  RETURN jsonb_array_length(v_avant) - jsonb_array_length(v_apres);
END $function$

CREATE OR REPLACE FUNCTION public.residence_bonus_nuit_interne(p_nom text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m record; v_jour date := (now() AT TIME ZONE 'Europe/Paris')::date; g boolean;
BEGIN
  SELECT l.* INTO m FROM public.residence_locations l JOIN public.personnages_donnees d ON d.name = l.locataire
   WHERE l.locataire = p_nom AND l.fin > now() AND d.current_building = 'residence-imperiale-novomirsk' AND d.current_room = l.piece
     AND l.nuit_bonus IS DISTINCT FROM v_jour
   ORDER BY l.fin DESC LIMIT 1 FOR UPDATE OF l;
  IF NOT FOUND THEN RETURN; END IF;
  g := m.piece = 'grand_appartement';
  PERFORM public.jauges_effet_appliquer_interne(p_nom, CASE WHEN g THEN 15 ELSE 4 END, CASE WHEN g THEN 15 ELSE 4 END, 0);
  UPDATE public.personnages_donnees
     SET resources = jsonb_set(CASE WHEN jsonb_typeof(resources) = 'object' THEN resources ELSE '{}'::jsonb END, '{dis}',
           to_jsonb(least(100, coalesce(CASE WHEN jsonb_typeof(resources->'dis') = 'number' THEN (resources->>'dis')::numeric END, 50)
                               + CASE WHEN g THEN 5 ELSE 4 END)))
   WHERE name = p_nom;
  UPDATE public.residence_locations SET nuit_bonus = v_jour WHERE id = m.id;
END $function$

CREATE OR REPLACE FUNCTION public.serrure_batiment_ferme_interne(p_nom text, p_pays text, p_ville text, p_batiment text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF p_batiment IS NULL OR NOT EXISTS (SELECT 1 FROM public.serrures WHERE statut = 'posee' AND cible = 'batiment' AND fermee
       AND (pays, ville, batiment) = (p_pays, p_ville, p_batiment)) THEN RETURN false; END IF;
  PERFORM public.serrures_fin_bail_interne(p_pays, p_ville, p_batiment, NULL);
  SELECT id INTO v_id FROM public.serrures WHERE statut = 'posee' AND cible = 'batiment' AND fermee
     AND (pays, ville, batiment) = (p_pays, p_ville, p_batiment);
  RETURN v_id IS NOT NULL AND NOT public.serrure_cle_detenue_interne(p_nom, v_id);
END $function$

CREATE OR REPLACE FUNCTION public.serrure_porte_fermee_interne(p_nom text, p_pays text, p_ville text, p_batiment text, p_piece text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF p_batiment IS NULL OR p_piece IS NULL THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.serrures WHERE statut = 'posee' AND cible = 'lieu' AND fermee
                   AND (pays, ville, batiment, piece) = (p_pays, p_ville, p_batiment, p_piece)) THEN RETURN false; END IF;
  PERFORM public.serrures_fin_bail_interne(p_pays, p_ville, p_batiment, p_piece);
  SELECT id INTO v_id FROM public.serrures WHERE statut = 'posee' AND cible = 'lieu' AND fermee
     AND (pays, ville, batiment, piece) = (p_pays, p_ville, p_batiment, p_piece);
  RETURN v_id IS NOT NULL AND NOT public.serrure_cle_detenue_interne(p_nom, v_id);
END $function$

CREATE OR REPLACE FUNCTION public.sovarka_inventaire_ligne_interne(p_inv jsonb, p_cles text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE i integer;
BEGIN
  IF jsonb_typeof(p_inv) = 'array' THEN
    FOR i IN 0 .. jsonb_array_length(p_inv) - 1 LOOP
      IF (p_inv -> i ->> 'stackKey') = ANY (p_cles) AND coalesce((p_inv -> i ->> 'stackable')::boolean, false)
         AND coalesce((p_inv -> i ->> 'qty')::numeric, 0) >= 1 THEN
        RETURN jsonb_build_object('i', i, 'qte', floor((p_inv -> i ->> 'qty')::numeric)::integer, 'cle', p_inv -> i ->> 'stackKey');
      END IF;
    END LOOP;
  END IF;
  RETURN jsonb_build_object('i', -1, 'qte', 0);
END $function$

CREATE OR REPLACE FUNCTION public.sovarka_inventaire_retirer_interne(p_nom text, p_ligne jsonb, p_qte integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_inv jsonb; i integer := (p_ligne->>'i')::integer; q integer := (p_ligne->>'qte')::integer;
BEGIN
  SELECT coalesce(inventory, '[]'::jsonb) INTO v_inv FROM public.personnages_donnees WHERE name = p_nom FOR UPDATE;
  IF i < 0 OR q < p_qte OR (v_inv -> i ->> 'stackKey') IS DISTINCT FROM (p_ligne->>'cle') THEN RAISE EXCEPTION 'inventaire_ligne_invalide'; END IF;
  IF q = p_qte THEN v_inv := v_inv - i; ELSE v_inv := jsonb_set(v_inv, ARRAY[i::text, 'qty'], to_jsonb(q - p_qte)); END IF;
  UPDATE public.personnages_donnees SET inventory = v_inv, updated_at = now() WHERE name = p_nom;
  IF (SELECT inventory FROM public.personnages_donnees WHERE name = p_nom) IS DISTINCT FROM v_inv THEN
    RAISE EXCEPTION 'inventaire_non_applique'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.sovarka_palais_acces_interne(p_nom text, p_piece text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_pres text;
BEGIN
  IF p_piece IN ('appartements_president', 'salle_reception') THEN
    SELECT data::jsonb ->> 'eluId' INTO v_pres FROM public.cycles_electoraux WHERE id = 'soviet_president';
    IF v_pres IS NOT NULL AND (p_nom = v_pres OR EXISTS (
         SELECT 1 FROM public.groupes_pj_adhesions WHERE membre = p_nom AND chef = v_pres)) THEN
      RETURN NULL;
    END IF;
    RETURN 'groupe_president_requis';
  ELSIF p_piece = 'musee_presidentiel' THEN
    -- Le président visite son musée gratuitement (Fred, 08/11/2026).
    IF EXISTS (SELECT 1 FROM public.cycles_electoraux WHERE id = 'soviet_president' AND data::jsonb ->> 'eluId' = p_nom)
       OR EXISTS (SELECT 1 FROM public.sovarka_musee_billets
                WHERE jour = (now() AT TIME ZONE 'Europe/Paris')::date AND personnage = p_nom) THEN
      RETURN NULL;
    END IF;
    RETURN 'billet_musee_requis';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.navigation_commander_personnage_interne(p_nom text, p_mode text, p_destination text, p_piece text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE moi text; ids text[]; pnjs text[]; apres text[]; nom text; a record; r jsonb;
 deja boolean; positions jsonb;
BEGIN
 -- pays_physique_groupes_v1
 -- navigation_transaction_commune_v1
 IF p_mode NOT IN ('rue','piece') OR p_mode IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','mode_invalide'); END IF;
 moi:=p_nom;
 IF moi IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','non_authentifie'); END IF;
 -- Même verrou que l'adhésion/départ, avant toute lecture de composition.
 PERFORM pg_advisory_xact_lock(hashtextextended('groupe_pj:graphe',0));
 IF EXISTS(SELECT 1 FROM public.groupes_pj_adhesions WHERE membre=moi) THEN
  RETURN jsonb_build_object('ok',false,'raison','chef_de_groupe_requis'); END IF;
 SELECT array_agg(n ORDER BY n) INTO ids FROM (
  SELECT moi n UNION SELECT membre FROM public.groupes_pj_adhesions WHERE chef=moi) t;
 SELECT coalesce(array_agg(identifiant ORDER BY identifiant),'{}'::text[]) INTO pnjs
  FROM public.groupe_participants_interne(moi) WHERE NOT est_pj;
 -- Ordre commun avec les ordres PNJ et leurs projections institutionnelles.
 -- navigation_terrain_partage_v1
 IF p_mode='piece' THEN
 PERFORM t.id FROM public.terrains_etat t WHERE t.country=(SELECT country FROM public.personnages_donnees WHERE name=moi)
 AND t.building_id=p_destination ORDER BY t.id FOR SHARE;
 END IF;
 PERFORM public.pnj_groupes_verrouiller_projections_interne(pnjs);
 PERFORM name FROM public.personnages_donnees WHERE name=ANY(ids) ORDER BY name FOR UPDATE;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::text[]) INTO apres
  FROM public.pnj_membres WHERE leader_pj=ANY(ids);
 IF pnjs IS DISTINCT FROM apres THEN
  RETURN jsonb_build_object('ok',false,'raison','composition_modifiee'); END IF;
 PERFORM id FROM public.pnj_membres WHERE id=ANY(pnjs) ORDER BY id FOR UPDATE;
 SELECT country,current_city,current_building,current_room,current_street INTO a
  FROM public.personnages_donnees WHERE name=moi;
 IF (SELECT count(*) FROM public.personnages_donnees WHERE name=ANY(ids))<>cardinality(ids)
 OR EXISTS(SELECT 1 FROM public.personnages_donnees d WHERE d.name=ANY(ids)
  AND (d.country IS DISTINCT FROM a.country OR d.current_city IS DISTINCT FROM a.current_city
   OR d.current_building IS DISTINCT FROM a.current_building
   OR (a.current_building IS NOT NULL AND d.current_room IS DISTINCT FROM a.current_room)
   OR (a.current_building IS NULL AND d.current_street IS DISTINCT FROM a.current_street))) THEN
  RETURN jsonb_build_object('ok',false,'raison','groupe_disperse'); END IF;
 IF EXISTS(SELECT 1 FROM public.pnj_membres WHERE id=ANY(pnjs)
  AND (statut<>'actif' OR (SELECT pe.pays FROM public.pnj_position_effective(pnj_membres.id) pe) IS DISTINCT FROM a.country)) THEN
  RETURN jsonb_build_object('ok',false,'raison','membre_pnj_indisponible'); END IF;
 IF EXISTS(SELECT 1 FROM public.batailles_engagements e
  JOIN public.batailles b ON b.id=e.bataille_id
  JOIN public.pnj_soldats_metier sm ON sm.compagnie_id=e.compagnie_id AND sm.section_id=e.section_id AND sm.matricule=e.matricule
  WHERE sm.pnj_id=ANY(pnjs) AND e.sorti_round IS NULL AND b.statut='en_cours') THEN
  RETURN jsonb_build_object('ok',false,'raison','combat_membre_pnj'); END IF;
 -- Phase de validation : même moteur, aucune écriture ni dépense.
 FOREACH nom IN ARRAY ids LOOP
  r:=CASE WHEN p_mode='rue' THEN public.rue_position_personnage_interne(nom,p_destination,true) ELSE public.navigation_interieure_personnage_interne(nom,p_destination,p_piece,true) END;
  IF NOT coalesce((r->>'ok')::boolean,false) THEN
   RETURN r||jsonb_build_object('membre',nom); END IF;
 END LOOP;
 SELECT bool_and(CASE WHEN p_mode='rue' THEN current_building IS NULL AND current_street=p_destination ELSE current_building=p_destination AND current_room=p_piece END) INTO deja
  FROM public.personnages_donnees WHERE name=ANY(ids);
 BEGIN
 -- pays_physique_groupes_v1
  IF NOT coalesce(deja,false) THEN
   FOREACH nom IN ARRAY ids LOOP
    r:=CASE WHEN p_mode='rue' THEN public.rue_position_personnage_interne(nom,p_destination,false) ELSE public.navigation_interieure_personnage_interne(nom,p_destination,p_piece,false) END;
    IF NOT coalesce((r->>'ok')::boolean,false) THEN
     RAISE EXCEPTION USING ERRCODE='P2190',MESSAGE='mouvement_membre_refuse'; END IF;
   END LOOP;
   PERFORM public.pnj_groupes_projeter_interne(pnjs);
  END IF;
 EXCEPTION WHEN SQLSTATE 'P2190' THEN RETURN r||jsonb_build_object('membre',nom);
 END;
 SELECT jsonb_agg(jsonb_build_object('name',name,'country',country,'city',current_city,
   'building',current_building,'room',current_room,'street',current_street,'updated_at',updated_at) ORDER BY name)
  INTO positions FROM public.personnages_donnees WHERE name=ANY(ids);
 RETURN jsonb_build_object('ok',true,'noeud',CASE WHEN p_mode='rue' THEN p_destination END,'building',CASE WHEN p_mode='piece' THEN p_destination END,'room',p_piece,'deja_present',coalesce(deja,false),
   'chef',moi,'membres',to_jsonb(ids),'positions',positions);
END $function$

CREATE OR REPLACE FUNCTION public.navigation_interieure(p_batiment text, p_piece text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text := public.mon_personnage(); v_avant text; v jsonb; v_arr jsonb;
BEGIN
  SELECT current_building INTO v_avant FROM public.personnages_donnees WHERE name = v_moi;
  v := public.navigation_commander_interne('piece', p_batiment, p_piece);
  -- controles_entree_zone_serveur_v2 : patrouille du couvre-feu à l'entrée d'un bâtiment.
  IF v_moi IS NOT NULL AND p_batiment IS NOT NULL AND coalesce((v ->> 'ok')::boolean, false)
     AND v_avant IS DISTINCT FROM p_batiment THEN
    v_arr := public.controle_couvre_feu_interne(v_moi);
    IF v_arr IS NOT NULL THEN v := v || jsonb_build_object('arrestation', v_arr); END IF;
  END IF;
  RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.peine_acte_interne(p_acte text, p_pays text)
 RETURNS TABLE(libelle text, jours integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE i record; c record;
BEGIN
SELECT * INTO i FROM public.infractions WHERE id = p_acte;
IF FOUND AND coalesce(p_pays, 'republic') = 'republic' AND i.bareme_propre THEN libelle := i.libelle; jours := i.jours_reference; RETURN NEXT; RETURN; END IF;
SELECT * INTO c FROM public.infractions_categories WHERE id = coalesce(CASE WHEN FOUND THEN i.categorie END, p_acte);
IF NOT FOUND THEN SELECT * INTO c FROM public.infractions_categories WHERE id = 'delit_mineur'; END IF;
libelle := c.libelle; jours := c.jours_reference; RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.controle_couvre_feu_interne(p_nom text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p record; v_cf jsonb; v_heure integer := extract(hour FROM now() AT TIME ZONE 'Europe/Paris'); v_arr jsonb;
BEGIN
  SELECT country, poste, requisition, est_emprisonne INTO p FROM public.personnages_donnees WHERE name = p_nom;
  IF NOT FOUND OR p.est_emprisonne IS NOT NULL THEN RETURN NULL; END IF;
  SELECT b.data -> 'couvreFeu' INTO v_cf FROM public.budgets_nationaux b WHERE b.id = p.country;
  IF jsonb_typeof(v_cf) IS DISTINCT FROM 'object' OR NOT coalesce((v_cf ->> 'actif')::boolean, false)
     OR ((v_cf ->> 'dateFin') IS NOT NULL AND (extract(epoch FROM now()) * 1000) > (v_cf ->> 'dateFin')::numeric)
     OR NOT (v_heure >= 20 OR v_heure < 6)
     OR coalesce(p.poste ->> 'id', '') IN ('lieutenant', 'capitaine', 'commandant', 'min_def')
     OR coalesce(p.requisition ->> 'statut', '') IN ('convoque', 'affecte')
     OR random() >= 0.45 THEN
    RETURN NULL;
  END IF;
  v_arr := public.arrestation_flagrant_interne(p_nom, 'violation_couvre_feu', false, 'patrouille_couvre_feu');
  RETURN CASE WHEN coalesce((v_arr ->> 'ok')::boolean, false) THEN v_arr || jsonb_build_object('controle', 'couvre_feu') END;
END $function$

CREATE OR REPLACE FUNCTION public.immunite_militaire_interne(p_nom text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p record; v_emp text; v_ici text;
BEGIN
SELECT poste, domicile, country INTO p FROM public.personnages_donnees WHERE name = p_nom;
IF NOT FOUND OR coalesce(p.poste ->> 'id', '') NOT IN ('lieutenant', 'capitaine', 'commandant') THEN RETURN false; END IF;
v_ici := coalesce(p.country, 'republic');
v_emp := coalesce(CASE WHEN jsonb_typeof(p.domicile) = 'object' THEN p.domicile ->> 'country' END, v_ici);
IF EXISTS (SELECT 1 FROM public.guerres g WHERE coalesce(g.data ->> 'statut', g.statut) = 'active'
 AND ((g.data ->> 'attaquant' = v_emp AND g.data ->> 'attaque' = v_ici) OR (g.data ->> 'attaque' = v_emp AND g.data ->> 'attaquant' = v_ici))) THEN RETURN true; END IF;
RETURN v_ici = v_emp AND coalesce((SELECT (b.data ->> 'mobilisationNationaleActive')::boolean FROM public.budgets_nationaux b WHERE b.id = v_emp), false);
END $function$

CREATE OR REPLACE FUNCTION public.navigation_rue_trajet_interne(p_pays text, p_ville text, p_batiment text, p_rue text, p_noeud text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$DECLARE v_pj record;v_noeud public.rue_noeuds_serveur%ROWTYPE;v_depart text;BEGIN SELECT p_pays AS country,p_ville AS current_city,p_batiment AS current_building,p_rue AS current_street INTO v_pj; SELECT * INTO v_noeud FROM public.rue_noeuds_serveur WHERE country=v_pj.country AND city=v_pj.current_city AND noeud=p_noeud;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','noeud_inconnu'); END IF;
 IF v_pj.current_building IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM public.rue_sorties_batiments
 WHERE country=v_pj.country AND city=v_pj.current_city AND building=v_pj.current_building AND noeud=p_noeud) THEN
 RETURN jsonb_build_object('ok',false,'raison','sortie_invalide'); END IF;
 ELSIF v_pj.current_street IS NOT NULL AND v_pj.current_street<>p_noeud THEN
 IF NOT EXISTS(SELECT 1 FROM public.rue_noeuds_serveur
 WHERE country=v_pj.country AND city=v_pj.current_city AND noeud=v_pj.current_street
 AND p_noeud=ANY(voisins)) THEN RETURN jsonb_build_object('ok',false,'raison','trajet_invalide'); END IF;
 ELSIF v_pj.current_street IS NULL THEN
 v_depart:=CASE v_pj.current_city WHEN 'capitale' THEN 'luthecia-palais-presidentiel'
 WHEN 'ville_a' THEN 'psm-centre-multimodal' WHEN 'ville_b' THEN 'montrouge-vue-3' ELSE NULL END;
 IF p_noeud IS DISTINCT FROM v_depart THEN RETURN jsonb_build_object('ok',false,'raison','position_initiale_invalide'); END IF;
 END IF;
RETURN jsonb_build_object('ok',true);END;$function$

CREATE OR REPLACE FUNCTION public.detention_prolonger_interne(p_nom text, p_motifs jsonb, p_forcer_qhs boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_peine jsonb; v_det record; v_jours_supp int; v_nouveau int; v_motifs jsonb;
BEGIN
  IF p_motifs IS NULL OR jsonb_typeof(p_motifs) <> 'array' OR jsonb_array_length(p_motifs) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'motifs_absents');
  END IF;
  SELECT * INTO v_det FROM public.detention_active(p_nom);
  IF v_det.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'cible_non_detenue');
  END IF;
  SELECT coalesce(sum((m ->> 'jours')::int), 0) INTO v_jours_supp
    FROM jsonb_array_elements(p_motifs) m;
  v_nouveau := coalesce(v_det.jour_fin, 0) + v_jours_supp;
  -- Les motifs sont relus SOUS VERROU puis concatenes. La branche cliente, elle, les lisait
  -- avec `.catch(() => [])` : un echec de lecture ECRASAIT tous les motifs existants.
  SELECT coalesce(motifs, '[]'::jsonb) INTO v_motifs
    FROM public.detentions WHERE id = v_det.id FOR UPDATE;
  UPDATE public.detentions
     SET motifs = v_motifs || p_motifs, jour_fin = v_nouveau
   WHERE id = v_det.id;
  SELECT est_emprisonne INTO v_peine FROM public.personnages_donnees
   WHERE name = p_nom FOR UPDATE;
  IF v_peine IS NOT NULL AND jsonb_typeof(v_peine) = 'object' THEN
    UPDATE public.personnages_donnees
       SET est_emprisonne = v_peine
             || jsonb_build_object('jours', coalesce((v_peine ->> 'jours')::int, 0) + v_jours_supp)
             || jsonb_build_object('jourFin', v_nouveau)
     WHERE name = p_nom;
  END IF;
  IF p_forcer_qhs THEN
    PERFORM public.detention_qhs_poser_interne(p_nom, v_det.id,
              coalesce(p_motifs -> 0 ->> 'type', 'Sentence'));
  END IF;
  RETURN jsonb_build_object('ok', true, 'cible', p_nom, 'detention_id', v_det.id,
                            'jours_ajoutes', v_jours_supp, 'jour_fin', v_nouveau);
END; $function$

CREATE OR REPLACE FUNCTION public.navigation_commander_interne(p_mode text, p_destination text, p_piece text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE moi text := public.mon_personnage(); p record; v_dans boolean; v_vers boolean;
BEGIN
  -- sovarka_foret_chemins_v1 (10/11/2026)
  IF moi IS NOT NULL AND current_setting('rp.foret_passage', true) IS DISTINCT FROM 'on' THEN
    SELECT country, current_city, current_building, current_room INTO p FROM public.personnages_donnees WHERE name = moi;
    IF p.country = 'soviet' AND p.current_city = 'ville_b' THEN
      v_dans := p.current_building = 'zone-production' AND coalesce(p.current_room, '') LIKE 'foret_vue_%';
      v_vers := p_mode = 'piece' AND p_destination = 'zone-production' AND coalesce(p_piece, '') LIKE 'foret_vue_%';
      IF (v_dans OR v_vers) AND (p_mode <> 'piece' OR p.current_building IS DISTINCT FROM p_destination OR p.current_room IS DISTINCT FROM p_piece) THEN
        RETURN jsonb_build_object('ok', false, 'raison', CASE WHEN v_dans THEN 'foret_perdu' ELSE 'foret_chemin_aleatoire' END);
      END IF;
    END IF;
  END IF;
  RETURN public.navigation_commander_personnage_interne(moi, p_mode, p_destination, p_piece);
END $function$

CREATE OR REPLACE FUNCTION public.rue_position_personnage_interne(p_nom text, p_noeud text, p_verifier boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_nom text; v_pj public.personnages_donnees%ROWTYPE; v_noeud public.rue_noeuds_serveur%ROWTYPE;
 v_depart text;v_verdict jsonb; v_refus jsonb;
BEGIN
 -- navigation_disponibilite_commune_v1
 v_nom:=p_nom;
 v_refus:=public.navigation_disponibilite_interne(p_nom);
 IF NOT coalesce((v_refus->>'ok')::boolean,false) THEN RETURN v_refus; END IF;
 SELECT * INTO v_pj FROM public.personnages_donnees WHERE name=v_nom;
 v_verdict:=public.navigation_rue_trajet_interne(v_pj.country,v_pj.current_city,v_pj.current_building,v_pj.current_street,p_noeud);IF NOT coalesce((v_verdict->>'ok')::boolean,false) THEN RETURN v_verdict;END IF;
 IF p_verifier THEN RETURN jsonb_build_object('ok',true,'verifie',true); END IF;
 UPDATE public.personnages_donnees SET current_building=NULL,current_room=NULL,current_street=p_noeud,updated_at=clock_timestamp() WHERE id=v_pj.id;
 UPDATE public.police_interceptions SET expires_at=now() WHERE personnage=v_nom AND expires_at>now();
 RETURN jsonb_build_object('ok',true,'noeud',p_noeud);
END;
$function$

CREATE OR REPLACE FUNCTION public.arrestation_flagrant_interne(p_nom text, p_acte text, p_aggravation boolean, p_source text, p_libelle text DEFAULT NULL::text, p_jours integer DEFAULT NULL::integer, p_qhs boolean DEFAULT false, p_retour_ville text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p record; v_libelle text; v_jours integer; v_total integer; v_motifs jsonb; v_r jsonb;
 v_ts text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('groupe_pj:graphe', 0));
SELECT name, country, current_city, est_emprisonne, coalesce(day, 1) AS jour INTO p FROM public.personnages_donnees WHERE name = p_nom FOR UPDATE;
IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'raison', 'personnage_absent'); END IF;
IF public.immunite_militaire_interne(p_nom) THEN RETURN jsonb_build_object('ok', false, 'raison', 'immunite_militaire'); END IF;
IF p_jours IS NOT NULL THEN v_libelle := coalesce(p_libelle, 'Flagrant délit'); v_jours := p_jours;
ELSE SELECT b.libelle, b.jours INTO v_libelle, v_jours FROM public.peine_acte_interne(p_acte, p.country) b; END IF;
IF v_jours IS NULL OR v_jours < 1 THEN RAISE EXCEPTION 'arrestation_flagrant_interne : barème absent pour %', p_acte; END IF;
v_motifs := jsonb_build_array(jsonb_build_object('type', v_libelle, 'acte', p_acte, 'jour_fait', p.jour, 'city', p.current_city, 'jours', v_jours, 'source', 'flagrant_delit', 'date_evenement', v_ts));
v_total := v_jours;
IF p_aggravation THEN
 v_motifs := v_motifs || jsonb_build_array(jsonb_build_object('type', 'Résistance à l’arrestation', 'acte', 'resistance_arrestation', 'jour_fait', p.jour, 'city', p.current_city, 'jours', 2, 'source', 'flagrant_delit', 'date_evenement', v_ts));
 v_total := v_total + 2;
END IF;
IF p.est_emprisonne IS NOT NULL AND jsonb_typeof(p.est_emprisonne) = 'object' THEN
 IF NOT p_qhs THEN RETURN jsonb_build_object('ok', false, 'raison', 'deja_detenu'); END IF;
 v_r := public.detention_prolonger_interne(p_nom, v_motifs, true);
ELSE
 v_r := public.detention_ouvrir_interne(p_nom, v_libelle, v_total, p.current_city, p.country, v_motifs, 'flagrant_delit', p_source,
   CASE WHEN p_retour_ville IS NOT NULL THEN jsonb_build_object('retour_ville', p_retour_ville) ELSE '{}'::jsonb END);
 IF coalesce((v_r ->> 'ok')::boolean, false) AND p_qhs THEN PERFORM public.detention_qhs_poser_interne(p_nom, v_r ->> 'detention_id', v_libelle); END IF;
END IF;
IF NOT coalesce((v_r ->> 'ok')::boolean, false) THEN RETURN v_r; END IF;
PERFORM set_config('rp.recherche_interne', 'on', true);
UPDATE public.personnages_donnees d SET recherche = coalesce((SELECT jsonb_agg(e ORDER BY o) FROM jsonb_array_elements(d.recherche) WITH ORDINALITY x(e, o)
 WHERE NOT (e ->> 'acte' = p_acte AND (e ->> 'country' IS NULL OR e ->> 'country' = p.country))), '[]'::jsonb)
 WHERE d.name = p_nom AND jsonb_typeof(d.recherche) = 'array';
RETURN v_r || jsonb_build_object('ok', true, 'acte', p_acte, 'raison_peine', v_libelle, 'jours', v_total, 'qhs', p_qhs);
END $function$
